window.POEM_DB=window.POEM_DB||{};POEM_DB["song_037"]={"n":"王之道","dyn":"宋","poems":[{"t":"七夕苦旱望雨","f":"七言绝句","c":["田禾吐白将就槁，野草垂黄几欲燃。","来日天孙嫁河鼓，洗车今喜有夤缘。"]},{"t":"又送道者王法圆作丐","f":"五言绝句","c":["誓将三寸舌，求结万人缘。","宝刹成功日，当期道法圆。"]},{"t":"下阁道中","f":"七言绝句","c":["小桥流水数家村，春入川原日自暾。","马上不知岚气重，误惊征袖湿啼痕。"]},{"t":"山西庄舍赠信上人和彦时兄四首 其四","f":"七言绝句","c":["寒鸦成阵下遥村，冰合回塘镜一番。","㶁㶁溪流响何处，乱山无数不知源。"]},{"t":"山西庄舍赠信上人和彦时兄四首 其三","f":"七言绝句","c":["一枝清瘦早梅春，风味高如郭泰巾。","襟袖归来香未歇，要将佳句属诗人。"]},{"t":"山西庄舍赠信上人和彦时兄四首 其二","f":"七言绝句","c":["四壁萧然犬自驯，年来食粥甑生尘。","相逢未暇寒温语，请效参寥作故人。"]},{"t":"山西庄舍赠信上人和彦时兄四首 其一","f":"七言绝句","c":["十里西畴路半砠，短辕无力困瘏痡。","支筇预作渊明具，瓮有乌程不用沽。"]},{"t":"山茶","f":"七言绝句","c":["开花不与众芳期，先得江梅破白时。","犀甲鹤头微带雪，画屏曾见两三枝。"]},{"t":"乌江道中闻杜鹃有感","f":"七言绝句","c":["麻叶蓬蓬小麦肥，杨花风里杜鹃啼。","故园尚阻归来赋，惭愧东坡雨一犁。"]},{"t":"书子莱丙戌登科题名小录后","f":"七言绝句","c":["屈指宣和岁在辰，于今四十有三春。","吾家又得莱追继，丛桂从兹不乏人。"]},{"t":"书来上人房","f":"七言绝句","c":["十里清风水拍天，老僧斋罢抱头眠。","丹楹画栋看摧压，好为僧伽作胜缘。"]},{"t":"书源上人壁","f":"七言绝句","c":["丹枫黄槲壮秋容，诘曲僧房一径通。","塔似道人飞白笔，开窗还见倚晴空。"]},{"t":"风雨损花","f":"七言绝句","c":["雨多南国惜春归，多谢诗人赋采菲。","堕白残红无处着，漫随风絮作团飞。"]},{"t":"丘城道中","f":"七言绝句","c":["翠巘中间白水边，野梅官柳似当年。","正看绕树下残日，便觉前村生晚烟。"]},{"t":"冬日出郊二首 其二","f":"七言绝句","c":["一鞭乘兴上山头，雨脚随风湿破裘。","冬日有情还可爱，忽开云雾见林丘。"]},{"t":"冬日出郊二首 其一","f":"七言绝句","c":["覆块青青麦欲齐，田家篱落柘冈西。","岁饥冬暖聊相补，抉藕归来饷莱妻。"]},{"t":"出合肥北门二首 其二","f":"七言绝句","c":["断垣甃石新修叠，折戟埋沙旧战场。","阛阓凋零煨烬里，春风生草没牛羊。"]},{"t":"出合肥北门二首 其一","f":"七言绝句","c":["淮水东来没踝无，只今南北断修涂。","东风却与人心别，布暖吹生遍八区。"]},{"t":"北去安丰","f":"七言绝句","c":["问言何处是安丰，人指湖光柳影东。","欲识淮西真使者，一鞭追骥有诗翁。"]},{"t":"永丰道上阻水","f":"七言绝句","c":["路穷得水欲何为，立马逢人问所之。","十里归来同小愒，一鞭南去不踰时。"]},{"t":"玉树花","f":"七言绝句","c":["几年埋没乱荆榛，轩槛移来特地新。","何事临风忍相对，伤心一曲旧亡陈。"]},{"t":"再用韵赠湖塘来上人二首 其二","f":"七言绝句","c":["湖水瀰瀰浸绿苔，湖边衰柳两三栽。","游鱼得意潜还跃，幽鸟多情去复来。"]},{"t":"再用韵赠湖塘来上人二首 其一","f":"七言绝句","c":["望外荆榛蔽辋川，我来何必为逃喧。","乱馀村疃鸡豚尽，秋到江湖藻荇繁。"]},{"t":"合寨陪诸公观月","f":"七言绝句","c":["一樽相对夜厌厌，风捲浮云见玉蟾。","凌乱请看矛作舞，清光炯炯已窥檐。"]},{"t":"回峰寺和浮屠坦然韵","f":"七言绝句","c":["昼睡醒来日过中，山光入座水函空。","绿杨堤外荷花富，招致清香赖有风。"]},{"t":"安丰道中","f":"七言绝句","c":["水满陂塘草满川，望中茅屋起孤烟。","十年不踏安丰路，遂与清淮作次边。"]},{"t":"早发橐皋","f":"七言绝句","c":["春秋遗迹旧山川，鲁破吴亡久寂然。","恰到前年征战处，数间茅屋起炊烟。"]},{"t":"次韵赵积中慈湖即事 其二","f":"七言绝句","c":["干戈九载予心哀，乱离谁复歌南陔。","喜君父母老相守，调官仍逐金陵来。"]},{"t":"次韵赵积中慈湖即事 其四","f":"七言绝句","c":["嗟予留滞行当归，秋雨夜寒闻捣衣。","短檠明灭泪眼暗，谁令不寐心如飞。"]},{"t":"次韵赵积中慈湖即事 其五","f":"七言绝句","c":["山色湖光过雨清，江边归骑净无尘。","先生有酒快吾取，相逢少见如斯人。"]},{"t":"竹城道中","f":"七言绝句","c":["一溪清水浸馀霞，风里归鸿字脚斜。","今夜不知何处宿，路回山崦两三家。"]},{"t":"红梅","f":"七言绝句","c":["秾华不与众芳同，偏爱施朱立晓风。","莫道春来无酒病，脸霞犹带夜来红。"]},{"t":"西门道中闻人售田","f":"七言绝句","c":["走利奔权几日休，归来还复郭南游。","直饶心计奸如鬼，终恐输他善自谋。"]},{"t":"观梅和陈天予韵 其一","f":"七言绝句","c":["断桥疏竹带山幽，装点诗人觅句愁。","多谢双鱼传尺素，绝胜斗酒得凉州。"]},{"t":"观梅和陈天予韵 其二","f":"七言绝句","c":["春风草木初萌动，夜雨池塘正拍浮。","玉骨檀心清更好，对花何惜醉扶头。"]},{"t":"过广德宿开元寺上人房","f":"七言绝句","c":["满城花草斗欣荣，嫩绿夭红照眼明。","会有禅房通野色，解鞍聊复憩予行。"]},{"t":"过水南题范谏议书室","f":"七言绝句","c":["函丈当年贮卧龙，笑谈曾记一尊同。","幅巾已起草庐在，寂寞溪山空晚风。"]},{"t":"过含山邮亭和子厚弟壁间韵三首 其三","f":"七言绝句","c":["开窗如见碧油幢，新竹春来过屋长。","渐近柴桑旧家路，清风来报稻花香。"]},{"t":"过含山邮亭和子厚弟壁间韵三首 其二","f":"七言绝句","c":["透云斜日影朦胧，树杪依微少女风。","景物重来正无恙，为君收拾向诗中。"]},{"t":"过含山邮亭和子厚弟壁间韵三首 其一","f":"七言绝句","c":["犯暑篮舆趁晓耕，东风迎面葛衣轻。","过山缭绕湖边路，杨柳阴中带月行。"]},{"t":"过段寨二首 其二","f":"七言绝句","c":["嫩绿夭红照眼明，物华春事暗相惊。","提壶不饮劝谁饮，正在竹丛深处鸣。"]},{"t":"过段寨二首 其一","f":"七言绝句","c":["随行知有笔如椽，不碍冥搜借榻眠。","酒醉诗成还上马，秋蛇春蚓任人传。"]},{"t":"含山驿中","f":"七言绝句","c":["日暖风轻昼睡馀，海棠娇褪玉肌肤。","杨花也似知人意，来趁飞红入座隅。"]},{"t":"吴兴舟中有作","f":"七言绝句","c":["一水濡须百里间，举头遥见水西山。","微波不动又终日，安得扁舟送我还。"]},{"t":"时雨二绝和赵积中韵 其二","f":"七言绝句","c":["白江州熟人炊玉，竞说前年斗万钱。","何事农夫太庸鄙，欲将豚酒谢苍天。"]},{"t":"时雨二绝和赵积中韵 其一","f":"七言绝句","c":["稻花时候一犁雨，天意从人无间然。","我亦摧颓穷甚矣，烦君试考小行年。"]},{"t":"芭蕉","f":"七言绝句","c":["秋风鸣玉雨疏疏，嫩绿临窗半卷舒。","似是相知慰牢落，朝来肯寄一缄书。"]},{"t":"和子厚弟九日登魏文振亭园七首 其六","f":"七言绝句","c":["宿雨飞花阻撷芳，寄题端欲为增光。","何时登揽快晴日，瀹茗挥毫看瑞香。"]},{"t":"和子厚弟九日登魏文振亭园七首 其五","f":"七言绝句","c":["雨馀东北望银屏，一带寒山映骨清。","谁道西风能换物，染红枫树亦多情。"]},{"t":"和子厚弟九日登魏文振亭园七首 其四","f":"七言绝句","c":["疏懒常嫌束带劳，年来见客强垂条。","不知此病容医否，沥沥真珠出小槽。"]},{"t":"和子厚弟九日登魏文振亭园七首 其三","f":"七言绝句","c":["一龛灯火夜凄清，壁下秋虫断续声。","细把新诗等风味，易牙元不乱淄渑。"]},{"t":"和子厚弟九日登魏文振亭园七首 其二","f":"七言绝句","c":["乱插黄花趁节宜，年华休向镜中悲。","已知和气回春谷，横管临风更一吹。"]},{"t":"和子厚弟九日登魏文振亭园七首 其一","f":"七言绝句","c":["潇洒湖东小小亭，一时酬唱有三明。","亭前澄练无边际，应助诗人写物情。"]},{"t":"和子厚弟九日登魏文振亭园七首 其七","f":"七言绝句","c":["官道千秋坐小车，仙随阮肇饭胡麻。","男儿正患无津耳，千古留侯事可嘉。"]},{"t":"和子厚弟冬至即事","f":"七言绝句","c":["天容如鉴地无尘，阳气依稀动紫荆。","日晷渐长端可爱，霜华增重不胜清。"]},{"t":"和子厚弟春日见寄三首 其三","f":"七言绝句","c":["十里西畴马送曛，晚风依约度溪云。","悬知今夜桃花雨，一洗焦枯慰使君。"]},{"t":"和子厚弟春日见寄三首 其二","f":"七言绝句","c":["一鞭春色去迢迢，溪上红妆笑语娇。","酒醉不知行客避，竞眠芳草斗裙腰。"]},{"t":"和子厚弟春日见寄三首 其一","f":"七言绝句","c":["睡起晴窗正忆渠，老兵声喏到前除。","新诗价重连城璧，便觉贫家富不虚。"]},{"t":"和卞养直见示三绝简圣书 其一","f":"七言绝句","c":["看君落笔走云烟，想见新丰醉少年。","龙脊旧堆骐骥种，义方今服乃翁贤。"]},{"t":"和卞养直见示三绝简圣书 其二","f":"七言绝句","c":["杨柳阴中乳燕飞，马头寒峭怯单衣。","胡麻知有谁人种，应怪东游未即归。"]},{"t":"和卞养直见示三绝简圣书 其三","f":"七言绝句","c":["迟日轻风过雨天，笑声何处送鞦韆。","清明已逼长安近，寄语先生快着鞭。"]},{"t":"和历阳守张仲智观梅五首 其五","f":"七言绝句","c":["出车何日劳师还，二圣归来喜见颜。","乞得此身终芰制，乱山茅屋两三间。"]},{"t":"和历阳守张仲智观梅五首 其四","f":"七言绝句","c":["夜烧红烛照梅花，刺史风流自一家。","待得残英上丹脸，韶华端复到山茶。"]},{"t":"和历阳守张仲智观梅五首 其三","f":"七言绝句","c":["谁似樊侯哲且明，解将勋业佐中兴。","自怜汨没毛锥子，空对东风咏使能。"]},{"t":"和历阳守张仲智观梅五首 其二","f":"七言绝句","c":["万事当从酒到休，子山那得许多愁。","绿樽翠杓梅花夕，不醉翻令恶客羞。"]},{"t":"和历阳守张仲智观梅五首 其一","f":"七言绝句","c":["一霎轻风过雨稀，满庭春色碎珠玑。","使君载酒花前醉，更有新诗为发挥。"]},{"t":"和天衣聪老五首 其五","f":"七言绝句","c":["绿杨芳草自年年，人老逢春重喟然。","六入傥能除旧习，三乘端许结新缘。"]},{"t":"和天衣聪老五首 其四","f":"七言绝句","c":["达磨东来不记年，一灯然处百灯然。","愿从清净求明了，应喜晨斋学省缘。"]},{"t":"和天衣聪老五首 其三","f":"七言绝句","c":["法华灵应著当年，今古何曾有间然。","不见后身房次律，却因和璞记前缘。"]},{"t":"和天衣聪老五首 其二","f":"七言绝句","c":["老怀归去几何年，吴越宗风久寂然。","闻说近来狮子吼，应将驴脚问生缘。"]},{"t":"和天衣聪老五首 其一","f":"七言绝句","c":["师去无为十五年，重来猿鹤亦忻然。","此生不负今朝祝，冀结龙华会里缘。"]},{"t":"和孔纯老江上避风题酒肆","f":"七言绝句","c":["对酒应从暮吹号，酒行还喜荐溪毛。","若将物象评诗思，须向江头看怒涛。"]},{"t":"和孔纯老别邻居钱进之醉寝留题","f":"七言绝句","c":["不敢支筇问起居，虑烦炰脍破兵厨。","杜门终日无人顾，新竹墙头出万夫。"]},{"t":"和孔纯老按属邑六首 其六","f":"七言绝句","c":["榛莽无边没尽头，当年禾稼压田畴。","流亡复业知何日，九叙宜先戒用休。"]},{"t":"和孔纯老按属邑六首 其五","f":"七言绝句","c":["石窦泠泠注竹溪，溪光浮动软琉璃。","幽人爱玩不忍去，觅句坐惊红日西。"]},{"t":"和孔纯老按属邑六首 其四","f":"七言绝句","c":["客里宵寒梦易醒，起看残月照窗明。","招提正在山多处，过雨流泉碎玉鸣。"]},{"t":"和孔纯老按属邑六首 其三","f":"七言绝句","c":["行并焦湖试问涂，何如震泽占姑苏。","提壶聒聒劝谁饮，我不知君渠自呼。"]},{"t":"和孔纯老按属邑六首 其二","f":"七言绝句","c":["云涛雪浪渺无边，一簇溪桥客聚船。","舆卫欲休红日下，几家茅舍起炊烟。"]},{"t":"和孔纯老按属邑六首 其一","f":"七言绝句","c":["野云和雨渡金湖，山色微风恍有无。","不惯扁舟浮浩渺，且驱羸马上崎岖。"]},{"t":"和王元渤留题松寿岩白云庵寄郑顾道二首 其二","f":"七言绝句","c":["日影曈昽霁晓雰，几声幽鸟隔窗闻。","谢安盍为苍生起，休恋青山卧白云。"]},{"t":"和王元渤留题松寿岩白云庵寄郑顾道二首 其一","f":"七言绝句","c":["流水泠泠浸稻田，岩耕应费买山钱。","风梢雨盖摩霄汉，个里高人即地仙。"]},{"t":"和王觉民双泉道中","f":"七言绝句","c":["白云深处是吾家，山市归来日影斜。","独立前村聊送目，孤村流水闹寒鸦。"]},{"t":"和王圜中道上初见梅花二首 其二","f":"七言绝句","c":["安养疮痍过所亲，野人何幸预斯民。","自怜枯槁无生意，遂与寒梅竞得春。"]},{"t":"和王圜中道上初见梅花二首 其一","f":"七言绝句","c":["马头惊见一枝新，夹道欢呼拥吏民。","咫尺招提鸡黍约，不妨同醉万家春。"]},{"t":"和由字韵","f":"七言绝句","c":["当年相望见无由，千里荆襄隔数州。","时得新诗夸好句，服膺何止钓槎头。"]},{"t":"和刘春卿秋夜对月","f":"七言绝句","c":["天宇澄清桂影秋，骚人乘兴欲登楼。","楼前白水三千顷，滉滉镕银烂不收。"]},{"t":"和刘春卿晓起读书","f":"七言绝句","c":["梦断幽禽恰转更，窥窗残月淡孤灯。","孜孜读诵如吾子，指日菁莪看锡朋。"]},{"t":"和吕子梅题陈倅窗前新栽竹二首 其二","f":"七言绝句","c":["自是清阴能借润，不应积雨尚流寒。","先生端的磻溪裔，乞与沧溟作钓竿。"]},{"t":"和吕子梅题陈倅窗前新栽竹二首 其一","f":"七言绝句","c":["封殖要当同种玉，翱翔端复见停鸾。","此君不是尘中物，岂减樊川十万竿。"]},{"t":"和因上人四首 其四","f":"七言绝句","c":["荼蘼花底照衰颜，风送馀香到酒间。","春色他年尚无恙，红裙来继谢东山。"]},{"t":"和因上人四首 其三","f":"七言绝句","c":["水云深处见人烟，桑柘鸣鸠似可怜。","却怪银泥环四壁，由来春雨上蜗涎。"]},{"t":"和因上人四首 其二","f":"七言绝句","c":["茭葑弥天眼界幽，浇愁应办酒如油。","坐怜渔父机心胜，万顷春苗不下鸥。"]},{"t":"和因上人四首 其一","f":"七言绝句","c":["拍天湖水乱蛙鸣，雨脚随风泼细尘。","翠幄不开杨柳晚，红云初坐海棠春。"]},{"t":"和张元礼水仙花二首 其二","f":"七言绝句","c":["沉水香浓画不烟，赋花谁是饮中仙。","顾予老拙辞源涩，空想东坡万斛泉。"]},{"t":"和张元礼水仙花二首 其一","f":"七言绝句","c":["素颊黄心破晓寒，叶如谖草臭如兰。","一樽坐对东风软，敢比江梅取次看。"]},{"t":"和张文伯先梅后雪","f":"七言绝句","c":["六花无怪索诗催，正恐清寒勒早梅。","待得江头千树暗，故争明洁逐风来。"]},{"t":"和张文伯春日劝农","f":"七言绝句","c":["奉诏欢均草莽臣，郊原风日自温温。","欲知太守催耕意，重谷劭农本圣恩。"]},{"t":"和张文伯洞庭柑","f":"七言绝句","c":["金苞照俎出双柑，想见和枝映笋篮。","欲倩玉纤分玉液，要濡燥吻发清谈。"]},{"t":"和张文伯黄悦之席上赋雪","f":"七言绝句","c":["功成三白到春回，好放云天万里开。","今夜子猷方对客，却烦安道过溪来。"]},{"t":"和沈次韩春日郊行二首 其二","f":"七言绝句","c":["山色新晴一蘸青，隔溪无数野花明。","杞苗荻笋肥应美，采掇何妨趁晚烹。"]},{"t":"和沈次韩春日郊行二首 其一","f":"七言绝句","c":["杨花落地鸊鹈飞，百里湖山碧四围。","信步不知行几远，却怜芳草伴人归。"]},{"t":"和陈天予经过南巢邑人迎旧尹","f":"七言绝句","c":["君来井邑笑烘烘，君去萧条迥不同。","似说攀辕如昨日，可怜身老长儿童。"]},{"t":"和陈勉仲大宁院见寄","f":"七言绝句","c":["使驿驰驱赋陟冈，等閒诗戏况逢场。","清和在序芳菲歇，草色连天水满塘。"]},{"t":"和陈勉仲四首 其四","f":"七言绝句","c":["雨过山前草木苏，开窗澄碧渺金湖。","近来翰墨君为绝，喜见诗中有画图。"]},{"t":"和陈勉仲四首 其三","f":"七言绝句","c":["拍天湖水注东关，水外渔舟破浪还。","谁似老僧閒有味，清风一榻面佳山。"]},{"t":"和陈勉仲四首 其二","f":"七言绝句","c":["何日清游继大苏，扁舟东去泛西湖。","欲将景物和诗句，写作钱塘伟观图。"]},{"t":"和陈勉仲四首 其一","f":"七言绝句","c":["清风为我晓开关，风外浮云过雨还。","湛湛可怜清上下，一篙溪水水边山。"]},{"t":"和陈勉仲赠淮西漕吴介之二首 其二","f":"七言绝句","c":["九郡疮痍赖拊存，年来和气浃江村。","此恩未易论天报，请看于公大里门。"]},{"t":"和陈勉仲赠淮西漕吴介之二首 其一","f":"七言绝句","c":["威严霜肃德春阳，民感澄清涕泗滂。","畏垒大穰知不晚，三年端可笑庚桑。"]},{"t":"和彦立兄赠信上人","f":"七言绝句","c":["鼎社年来得志閒，一杯聊复效逃禅。","新诗莫漫惊流俗，恐被旁人唤皎然。"]},{"t":"和彦时兄赠觉上人化灯","f":"七言绝句","c":["江上相逢试问津，杖藜来作化灯行。","欲知照破无明窟，佛殿荧荧一点明。"]},{"t":"和彦逢弟简相山古上人二首 其二","f":"七言绝句","c":["蒿艾深迷古径苔，荒凉菊坞与松栽。","稻田正似人无几，赖有高僧伴我来。"]},{"t":"和彦逢弟简相山古上人二首 其一","f":"七言绝句","c":["相山风物似斜川，岑寂那知市井喧。","岁旱但伤禾穗槁，秋饥犹喜栗皱繁。"]},{"t":"和赵积中","f":"七言绝句","c":["日下高城月入扉，蒲葵不动晚风微。","幽人信步如相过，买酒黄公一醉归。"]},{"t":"和赵积中白莲三首 其三","f":"七言绝句","c":["耻同流辈弄胭脂，一样新裁雪白衣。","何日与君携酒去，两般分取载将归。"]},{"t":"和赵积中白莲三首 其二","f":"七言绝句","c":["清风习习晚香微，坐使诗人赋采菲。","想见温泉初濯玉，侍儿娇拥太真妃。"]},{"t":"和赵积中白莲三首 其一","f":"七言绝句","c":["翠盖亭亭水满塘，六铢新制带天香。","晚来扶洗娇无力，尽斗冰肌不斗妆。"]},{"t":"和徐伯远无为道中","f":"七言绝句","c":["江南五月稻抽芒，想见含花带露香。","底事淮乡太迟晚，一犁新雨正开荒。"]},{"t":"和徐伯远见寄三首 其三","f":"七言绝句","c":["三诗自可当尺书，得书何必须双鱼。","黄花强把酬雪白，丐君捧腹聊轩渠。"]},{"t":"和徐伯远见寄三首 其二","f":"七言绝句","c":["新炊香软桃花红，蕲州竹簟初出筒。","老翁易饱更甘寝，便便一觉南窗风。"]},{"t":"和徐伯远见寄三首 其一","f":"七言绝句","c":["我家湖上面九华，无钱买山山见赊。","待栽北牖一坡竹，追配东门千载瓜。"]},{"t":"和徐季功舒蕲道中二十首 其二十","f":"七言绝句","c":["光风习习日晖晖，堕絮飞红积渐稀。","芍药酴醾看正好，一尊能共送春归。"]},{"t":"和徐季功舒蕲道中二十首 其十九","f":"七言绝句","c":["灊皖归来麦已秋，相从时说白云游。","八年不践同安境，梦里山溪记旧由。"]},{"t":"和徐季功舒蕲道中二十首 其十八","f":"七言绝句","c":["怪石形模老牯同，漫将名字责农功。","得来正与齐田类，谁敢言耕望岁丰。"]},{"t":"和徐季功舒蕲道中二十首 其十七","f":"七言绝句","c":["下马邮亭忽喟然，数间茅屋起孤烟。","山花狼籍馀无几，断送归心起杜鹃。"]},{"t":"和徐季功舒蕲道中二十首 其十六","f":"七言绝句","c":["带雨酴醾不自持，短垣高榭倚斜枝。","野人莫觅丹青手，摹写春容一绝诗。"]},{"t":"和徐季功舒蕲道中二十首 其十五","f":"七言绝句","c":["庭閒人静鸟窥帘，坐对文书亦倦拈。","春旱正须三尺雨，江湖宁放老蛟潜。"]},{"t":"和徐季功舒蕲道中二十首 其十四","f":"七言绝句","c":["日迟风细午阴微，柳外青骢去若飞。","过得水村闻笑语，几家扶得醉人归。"]},{"t":"和徐季功舒蕲道中二十首 其十三","f":"七言绝句","c":["欲识吾君圣与仁，泽流寰海众熙春。","两淮饥馑方移粟，六辔驰驱不惮勤。"]},{"t":"和徐季功舒蕲道中二十首 其十二","f":"七言绝句","c":["草色青青入烧痕，登临何处暗销魂。","应怜野老无拘缚，种竹栽花教子孙。"]},{"t":"和徐季功舒蕲道中二十首 其十一","f":"七言绝句","c":["晓光晴影正曈昽，转眼还惊日过中。","芳草岸头人渡水，洛阳影里鸟呼风。"]},{"t":"和徐季功舒蕲道中二十首 其十","f":"七言绝句","c":["春云漠漠雨纤纤，花柳丛边见酒帘。","心为惜春无处著，可堪啼鸟更般添。"]},{"t":"和徐季功舒蕲道中二十首 其九","f":"七言绝句","c":["一夜西风作晓晴，纷然花草斗欣荣。","苍松巧与夭桃并，漫使诗人意不平。"]},{"t":"和徐季功舒蕲道中二十首 其八","f":"七言绝句","c":["山下溪边阿母家，春雷初过茗生芽。","马头睡思浓无那，一椀何妨泛乳花。"]},{"t":"和徐季功舒蕲道中二十首 其七","f":"七言绝句","c":["草满池塘水满川，雨馀溪溜正溅溅。","黄梅恰在山多处，披雾时看一握天。"]},{"t":"和徐季功舒蕲道中二十首 其六","f":"七言绝句","c":["野鸟关关督驾犁，及时新雨土膏肥。","知君有意农夫劝，故故穿林傍马飞。"]},{"t":"和徐季功舒蕲道中二十首 其五","f":"七言绝句","c":["三日春霖发土毛，道傍芳草半人高。","马头问是棠梨市，一片梨花映小桃。"]},{"t":"和徐季功舒蕲道中二十首 其四","f":"七言绝句","c":["拍溪春水鸭头青，溪上哦诗醉眼醒。","不见梅花寒蘸影，野桃山杏自娉婷。"]},{"t":"和徐季功舒蕲道中二十首 其三","f":"七言绝句","c":["溪流滟滟草凄凄，春日农郊麦穗齐。","捲地东风还作恶，片云随马渡溪低。"]},{"t":"和徐季功舒蕲道中二十首 其二","f":"七言绝句","c":["一声何处叫提壶，杨柳阴中驻犊车。","笑语谁家騃儿女，浣沙溪上数游鱼。"]},{"t":"和徐季功舒蕲道中二十首 其一","f":"七言绝句","c":["春阴连日竟何如，逐妇应怜拙勃姑。","习习晚风来更急，欲吹时雨助虚枯。"]},{"t":"和秦寿之春晚偶成八绝 其八","f":"七言绝句","c":["带雨飞来燕一双，问伊何事为春忙。","野人不解呢喃意，勉强搜吟对麦光。"]},{"t":"和秦寿之春晚偶成八绝 其五","f":"七言绝句","c":["欲下荒庭意已阑，一枝红药坐中看。","东风不息成何事，又酝春阴作夜寒。"]},{"t":"和秦寿之春晚偶成八绝 其四","f":"七言绝句","c":["官閒时醉秀溪春，醉里吟诗字字新。","欲报自惭无好语，年来胸次亦埃尘。"]},{"t":"和秦寿之春晚偶成八绝 其三","f":"七言绝句","c":["花外霏微雨弄晴，乱红狼藉过清明。","伤春正苦无聊甚，接接欣闻噪鹊声。"]},{"t":"和秦寿之春晚偶成八绝 其一","f":"七言绝句","c":["相从辄莫太匆匆，赌酒分茶自有功。","谁谓春归无处觅，柳蹊飞絮乱因风。"]},{"t":"和秦寿之春晚偶成八绝 其七","f":"七言绝句","c":["春来谈笑数追陪，多谢传杯不放杯。","醉里狂言应可笑，问春归去几时回。"]},{"t":"和秦寿之铜陵江上二首 其二","f":"七言绝句","c":["烟销远水分帆影，木落疏林出斧痕。","啸咏不知红日下，九华何处望中昏。"]},{"t":"和秦寿之铜陵江上二首 其一","f":"七言绝句","c":["枫叶霜馀霞灿烂，苇花风起雪纵横。","铜陵江上秋容好，两绝新诗取次成。"]},{"t":"和章序臣梅花二首 其二","f":"七言绝句","c":["多谢苍头语我来，恍如相见笑相陪。","新诗高妙梅清绝，展读花前病眼开。"]},{"t":"和章序臣梅花二首 其一","f":"七言绝句","c":["三月诗筒绝往来，有时谈麈许追陪。","梅花雅欲撩佳句，犯雪凌霜为我开。"]},{"t":"和富公权宗丞十首 其六","f":"七言绝句","c":["昂昂野鹤在鸡群，一见人分浊与清。","吟对红葵朝雨细，坐临绿竹午风轻。"]},{"t":"和富公权宗丞十首 其九","f":"七言绝句","c":["嗟予少也戆无奇，才力而今老更衰。","文阵异时逢大敌，犹能斩将复搴旗。"]},{"t":"和富公权宗丞十首 其八","f":"七言绝句","c":["恶客未尝知酒圣，高人何止擅文豪。","三司自揣非吾事，敢觊徐州解佩刀。"]},{"t":"和富公权宗丞十首 其十","f":"七言绝句","c":["我惭思涩同司马，君患才多继士衡。","今日相从非偶耳，挂冠淮浙好寻盟。"]},{"t":"和富公权宗丞十首 其一","f":"七言绝句","c":["门外传来一轴诗，烂然蓬荜顿增辉。","匹夫不敢贪怀璧，什袭今从故府归。"]},{"t":"和富公权宗丞十首 其三","f":"七言绝句","c":["閒想当年啸咏声，一时人物斗峥嵘。","江山清壮今犹昔，谁谓丹青画不成。"]},{"t":"和富公权宗丞十首 其二","f":"七言绝句","c":["展读新诗次第看，管中文豹喜窥斑。","不知笔力能豪放，落纸云烟欬唾间。"]},{"t":"和富公权宗丞十首 其四","f":"七言绝句","c":["后来模楷复何人，千载风流郭泰巾。","欲睹诗豪兼草圣，一尊聊发洞庭春。"]},{"t":"和富公权宗丞十首 其五","f":"七言绝句","c":["行草应曾阅斗蛇，世情无识笑东家。","君看横雨随风势，纸纸清新字字斜。"]},{"t":"和道可","f":"七言绝句","c":["卧雨春头到地长，清风一榻借微凉。","棋声惊断高僧梦，起拨炉中未过香。"]},{"t":"和鲁如晦七夕","f":"七言绝句","c":["乞巧谁家绮席开，夜阑箫鼓趁虚催。","启明不为牵牛计，又放朝阳送曙来。"]},{"t":"和戴禹功幕府归来三首 其三","f":"七言绝句","c":["临淮终日鉴修眉，水外遥山尺五低。","我欲骑云叫阊阖，请将捕寇付平西。"]},{"t":"和戴禹功幕府归来三首 其二","f":"七言绝句","c":["客里诗成付漫书，清风一榻黑甜馀。","相山旧隐今分定，却是归来计不疏。"]},{"t":"和戴禹功幕府归来三首 其一","f":"七言绝句","c":["抖擞空肠一字无，下邳能复异时书。","中兴正欲平骄寇，莫若相如赋子虚。"]},{"t":"和魏定父早春十首 其十","f":"七言绝句","c":["南禅相望无多地，深谢高轩日见过。","归去山林遂閒放，却寻农圃问谁何。"]},{"t":"和魏定父早春十首 其九","f":"七言绝句","c":["辰瓜醉竹定何如，试问君家种莳书。","坐久幽窗转斜日，恰怜梅影上衣裾。"]},{"t":"和魏定父早春十首 其八","f":"七言绝句","c":["怪来庭砌堕寒梅，风笛数声清以哀。","两日枯肠餍蔬笋，不堪茗椀发轻雷。"]},{"t":"和魏定父早春十首 其七","f":"七言绝句","c":["㶁㶁溪流碎玉鸣，野梅随处伴行人。","归欤路出临邛市，准拟沉浮曲米春。"]},{"t":"和魏定父早春十首 其六","f":"七言绝句","c":["春到花梢一点红，吹嘘应谢晓来风。","南园缭绕城边路，无限诗情杖履中。"]},{"t":"和魏定父早春十首 其五","f":"七言绝句","c":["门前溪水绿萦回，风縠无边费剪裁。","待与东君写春色，好教红紫一时开。"]},{"t":"和魏定父早春十首 其四","f":"七言绝句","c":["晚来天意欲晴寒，幽鸟争春到舌端。","诗骨自怜山样瘦，酒肠君似海能宽。"]},{"t":"和魏定父早春十首 其三","f":"七言绝句","c":["依依杨柳绕溪斜，黑白溪头鹄伴鸦。","雨过芜菁自春色，一丛茅屋野人家。"]},{"t":"和魏定父早春十首 其二","f":"七言绝句","c":["安得都护胡青骢，与君并辔摇玲珑。","南溪今日冻初解，好看游鱼翻鬣红。"]},{"t":"和魏定父早春十首 其一","f":"七言绝句","c":["早从子美追懒真，近向长康得痴绝。","相逢可笑复可怜，君看稀疏鬓边雪。"]},{"t":"岳阳楼","f":"七言绝句","c":["云开层观切高寒，三面江湖一面山。","眼界不知多少远，望中幽鸟暮飞还。"]},{"t":"法云寺和汤立贤留题","f":"七言绝句","c":["寺占湖边数亩山，杖藜偷得一朝閒。","昨朝恰别居巢长，又喜新诗在壁间。"]},{"t":"经过合寨吊孟氏故居二首 其二","f":"七言绝句","c":["行过春泥没马深，几声幽鸟啭乔林。","感时恨别愁无那，赖有清樽慰此心。"]},{"t":"经过合寨吊孟氏故居二首 其一","f":"七言绝句","c":["藤梢棘刺失朱门，空想当年载酒樽。","天色重增行客恨，东风吹雨湿黄昏。"]},{"t":"青梅","f":"七言绝句","c":["疏白欺人侵短鬓，老红乘酒驻衰颜。","食梅已判非吾事，把读清诗忆故山。"]},{"t":"鸣山驿夜雨","f":"七言绝句","c":["夜来风雨晓还晴，沙路无泥快早行。","鸟语花容春自好，有生何处不安生。"]},{"t":"春日书事呈历阳县苏仁仲八首 其八","f":"七言绝句","c":["子美不应花解恼，次公何必酒而狂。","知君颇负风流债，安得司空惯窃香。"]},{"t":"春日书事呈历阳县苏仁仲八首 其七","f":"七言绝句","c":["猛风吹雨暮江头，烟草微茫一片愁。","双鲤不来无处问，欲寻归路转悠悠。"]},{"t":"春日书事呈历阳县苏仁仲八首 其六","f":"七言绝句","c":["学似卿家宜有法，人如我辈岂无情。","新诗早自推心服，幽会知谁付目成。"]},{"t":"春日书事呈历阳县苏仁仲八首 其五","f":"七言绝句","c":["公馀槐柳转斜日，吏散鸟雀来空庭。","康成书带可人意，坐见茸茸相对青。"]},{"t":"春日书事呈历阳县苏仁仲八首 其四","f":"七言绝句","c":["情似长江流不断，事如芳草刬还生。","此身何苦浮名绊，正拟花时取次行。"]},{"t":"春日书事呈历阳县苏仁仲八首 其三","f":"七言绝句","c":["似是东风恼客心，淹留行色故相禁。","扁舟正在江南岸，又扰浮云作暮阴。"]},{"t":"春日书事呈历阳县苏仁仲八首 其二","f":"七言绝句","c":["芳草池塘处处佳，竹篱茅屋野人家。","清明过了桃花尽，颇觉春容属菜花。"]},{"t":"春日书事呈历阳县苏仁仲八首 其一","f":"七言绝句","c":["篮舆兀醉出东门，赖有官舟为解纷。","流马木牛今已矣，其馀儿辈说三分。"]},{"t":"春日访道上人","f":"七言绝句","c":["陇麦如烟水满塘，路边桃李问柔桑。","道人不作渊明调，笑碾新茶看瑞香。"]},{"t":"春日偶成","f":"七言绝句","c":["短垣新雨上银泥，柳外幽花咫尺迷。","独喜流莺解人意，一声声傍绿窗啼。"]},{"t":"独步","f":"七言绝句","c":["雨晴烟渚白鸥乱，风过霜林红叶稀。","独步幽吟心正苦，却怜明月照人归。"]},{"t":"秋日即事二首 其二","f":"七言绝句","c":["枕缘睡熟来魂梦，衣为酣频带酒痕。","多事长红兼短白，雨馀相倚映江村。"]},{"t":"秋日即事二首 其一","f":"七言绝句","c":["潮退菰蒲风自倒，秋深菱芡雨应添。","怪来病眼双明甚，喜见遥山寸碧纤。"]},{"t":"秋日悯旱题香山庄舍","f":"七言绝句","c":["千里骄阳稼穑枯，人心穷极但天呼。","须烦岩壑为霖手，下泽苍生慰海隅。"]},{"t":"秋日野步和王觉民十六首 其十六","f":"七言绝句","c":["病怯酒杯微过量，瘦怜衣带颇宽痕。","伤心故国迷烟草，秋日荒凉处处村。"]},{"t":"秋日野步和王觉民十六首 其十四","f":"七言绝句","c":["更穷诗债应难欠，纵懒书淫亦自添。","水外修眉横翠巘，试凭张敞画浓纤。"]},{"t":"秋日野步和王觉民十六首 其十三","f":"七言绝句","c":["烟里山光陈水墨，云边日影乱青红。","新诗有画人难到，高压澄江五字工。"]},{"t":"秋日野步和王觉民十六首 其十二","f":"七言绝句","c":["雨开繁菊金无价，风皱平池鉴有痕。","日暮客帆何处落，柿林西畔荻花村。"]},{"t":"秋日野步和王觉民十六首 其十一","f":"七言绝句","c":["箪瓢不失生涯在，诗酒何当习气除。","欲倩雕弧落新雁，足间寻觅子卿书。"]},{"t":"秋日野步和王觉民十六首 其十","f":"七言绝句","c":["孤灯闪闪风还暗，清漏沉沉夜向添。","案上数枝漙露菊，可怜疏落嫩纤纤。"]},{"t":"秋日野步和王觉民十六首 其九","f":"七言绝句","c":["酒嫩细斟浮蚁绿，芡柔轻剥汗衫红。","搜罗物象嗟予拙，挥扫词章放子工。"]},{"t":"秋日野步和王觉民十六首 其八","f":"七言绝句","c":["雨晴庭户生秋意，潮落溪桥见水痕。","稻熟人家得相向，兵馀眼底两三村。"]},{"t":"秋日野步和王觉民十六首 其七","f":"七言绝句","c":["五穷韩愈烦驱逐，一室陈蕃倦扫除。","我有埙篪旧诗集，当令阿买为君书。"]},{"t":"秋日野步和王觉民十六首 其六","f":"七言绝句","c":["迂愚长与懒相兼，岁晚空馀白发添。","坐送夕阳还黯黯，倚看新月露纤纤。"]},{"t":"秋日野步和王觉民十六首 其五","f":"七言绝句","c":["荷叶倚风摇败绿，蓼花沾雨卧衰红。","物华虽逐穷秋老，诗句翻从壮岁工。"]},{"t":"秋日野步和王觉民十六首 其四","f":"七言绝句","c":["揉蓝拍岸秋涛信，列炬缘山夜烧痕。","枫叶经霜红更好，晚来扶杖过前村。"]},{"t":"秋日野步和王觉民十六首 其三","f":"七言绝句","c":["穷愁长怕诗撩拨，幽愤须凭酒破除。","对酒更遭诗债窘，可堪毛颖不中书。"]},{"t":"秋日野步和王觉民十六首 其二","f":"七言绝句","c":["桑林閒觉疏黄减，菜陇贫怜嫩绿添。","秋水接潮还潋滟，晚风吹雨乍廉纤。"]},{"t":"秋日野步和王觉民十六首 其一","f":"七言绝句","c":["芡觜静缄秋水碧，梨腮深抺夕阳红。","近来诗社争相胜，幽讨冥搜字字工。"]},{"t":"秋日野步和王觉民十六首 其十五","f":"七言绝句","c":["人言会饮辰嫌酉，我为求医日问除。","老去谁能遵百忌，秋来只欲上三书。"]},{"t":"给散告帖","f":"七言绝句","c":["曾随骁将远追奔，勇冠诸军继虎贲。","圣主念功知有自，一时高下拜新恩。"]},{"t":"追和东坡梅花十绝 其九","f":"七言绝句","c":["步入芳丛脚自轻，看来群卉眼偏明。","和羹有实休疑晚，况是东君旧着情。"]},{"t":"追和东坡梅花十绝 其四","f":"七言绝句","c":["问言何处是前村，万木号寒雪障昏。","安得梦为蝴蝶去，花间栩栩适吟魂。"]},{"t":"追和东坡梅花十绝 其十","f":"七言绝句","c":["山下溪头卖酒家，为谁低入屋檐斜。","蔬肠不柰村酤涩，笑挽长条沃井花。"]},{"t":"追和东坡梅花十绝 其八","f":"七言绝句","c":["绛跗檀口映冰肌，踏雪来看带雪枝。","一见遂能消鄙吝，汝南谁敢忽牛医。"]},{"t":"追和东坡梅花十绝 其六","f":"七言绝句","c":["醉眼昏昏午倦开，不堪诗债苦相催。","清香自是蠲烦药，为折霜蕤一朵来。"]},{"t":"追和东坡梅花十绝 其七","f":"七言绝句","c":["莫怪风前玉斝飞，饮酣初喜传花枝。","正当北雪消残后，恰直东风料峭时。"]},{"t":"追和东坡梅花十绝 其五","f":"七言绝句","c":["真香暗逐微风远，疏影低随淡日斜。","好在黄昏清浅意，一时收拾付诗家。"]},{"t":"追和东坡梅花十绝 其二","f":"七言绝句","c":["盈盈终日对妆台，一树临溪欲半开。","吟赏不须期烂漫，恐随春雨点苍苔。"]},{"t":"追和东坡梅花十绝 其一","f":"七言绝句","c":["春到梅梢日自和，动人芳气不须多。","清肌瘦骨如冰玉，瘴雾那能柰子何。"]},{"t":"追和东坡梅花十绝 其三","f":"七言绝句","c":["一池春水绿萦回，池上梅花暖自开。","想见温泉初出浴，六宫遥指太真来。"]},{"t":"追和贾明叔侯陟明二侍郎瑞香二首 其二","f":"七言绝句","c":["深院重帘数尺墙，对花何必竟烧香。","九龄风度高难挹，举世纷纷漫笏囊。"]},{"t":"追和贾明叔侯陟明二侍郎瑞香二首 其一","f":"七言绝句","c":["日午高人睡正浓，幽香初破碧山红。","忽然梦觉寻无处，会有东来一阵风。"]},{"t":"送心上人","f":"词","c":["西城畦稼卧黄云，似说千门许见分。","驴载马驮应不厌，一?牙齿正须君。"]},{"t":"送浮屠宗立东游二首 其二","f":"七言绝句","c":["西走漫偿行脚债，南游聊勘坐禅翁。","不知色力能强健，又复观潮过浙东。"]},{"t":"送浮屠宗立东游二首 其一","f":"七言绝句","c":["抚掌相逢一笑同，自言参学百无功。","蜜甜忘却十年苦，雷吼嚇成三日聋。"]},{"t":"送浮屠善慧","f":"七言绝句","c":["云涛霜巘正峥嵘，梦里清游觉尚惊。","师到西湖如得句，不妨频寄老书生。"]},{"t":"送浮屠道廓","f":"五言绝句","c":["一宿已先觉，四明那更游。","去来无所着，风日海山秋。"]},{"t":"送贾教授伟满罢东归","f":"七言绝句","c":["妙年才气擅超群，试吏来司泮水芹。","行矣玉堂应召直，忍将风袂与君分。"]},{"t":"送顾渚茶与孔纯老","f":"七言绝句","c":["晓来飞雪似欺春，尽把群芳点缀匀。","莫讶两旗分顾渚，要令佳句斗清新。"]},{"t":"送曾式古归建昌","f":"七言绝句","c":["两年说归明日归，江头草软花芬菲。","风调江净船行驶，好看芳草怀春晖。"]},{"t":"送道者史宝通作丐","f":"五言绝句","c":["昔日山前寺，兵馀扫地空。","汝今能协力，真是宝林通。"]},{"t":"重阳示二三友","f":"七言绝句","c":["龙山何处暮云黄，坐想前贤落帽狂。","萸实菊花良不恶，为君沽酒作重阳。"]},{"t":"荷花","f":"七言绝句","c":["亭亭青盖倚宫妆，新浴温泉体自香。","暂借青风来一霎，欲披云锦见蜂房。"]},{"t":"偶书","f":"七言绝句","c":["万事秋来只信缘，为谁清嚏晚风前。","断虹收尽廉纤雨，喜见江南八月天。"]},{"t":"宿大泉遇雨","f":"七言绝句","c":["我行常苦雨相随，旱甚民心若倒垂。","坐久云容肤寸合，愿同焦槁被甘滋。"]},{"t":"寄二儿","f":"七言绝句","c":["老懒谁能教子孙，静中犹喜读书声。","有如双凤传家学，令我闻风畏后生。"]},{"t":"寄梅花与曾子修","f":"七言绝句","c":["待船聊复驻征骖，手撚梅花望翠岚。","花似若人清绝俗，故从江北寄江南。"]},{"t":"晚晴 其一","f":"七言绝句","c":["飞霰飘飘堕晚风，乱山无数暮云同。","天工却似怜羁旅，又变霜华见碧空。"]},{"t":"晚憩闻雷","f":"七言绝句","c":["湖外山光入座来，水晶宫阙翠屏开。","纤纤细落催花雨，隐隐轻鸣启蛰雷。"]},{"t":"梅花十绝追和张文潜韵 其十","f":"七言绝句","c":["花前倾步溅狂澜，花外扶疏竹数竿。","带雪精神清更好，冰肌元惯朔风寒。"]},{"t":"梅花十绝追和张文潜韵 其五","f":"七言绝句","c":["檐花厌浥细如尘，渡口舟横不见人。","独喜霜蕤清照坐，旅怀虽恶未孤春。"]},{"t":"梅花十绝追和张文潜韵 其二","f":"七言绝句","c":["晓来飞雪缀林端，冰玉肌肤巧耐寒。","折得一枝红半吐，自挼香蕊当朝飧。"]},{"t":"梅花十绝追和张文潜韵 其七","f":"七言绝句","c":["素艳忽从江上见，清香还向雪中闻。","谁能送酒来相劳，为尔开尝对马军。"]},{"t":"梅花十绝追和张文潜韵 其六","f":"七言绝句","c":["凌霜冒雪报花期，大小群芳例是儿。","屈指春风无十日，东君元是旧相知。"]},{"t":"梅花十绝追和张文潜韵 其一","f":"七言绝句","c":["额黄肌粉斗新妆，春入园林度暗香。","留滞江南归未得，一枝聊复沃愁肠。"]},{"t":"梅花十绝追和张文潜韵 其四","f":"七言绝句","c":["竹外山前见嫩黄，水沉清渍雪肌香。","应嫌桃李风姿俗，故作寻常淡淡妆。"]},{"t":"梅花十绝追和张文潜韵 其九","f":"七言绝句","c":["别后开园日就荒，对花还忆少年狂。","东荣几树应无恙，待得予归破嫩黄。"]},{"t":"梅花十绝追和张文潜韵 其三","f":"七言绝句","c":["年年常是犯凝寒，换骨曾凭九转丹。","结实和羹知不晚，试尝花蕊味应酸。"]},{"t":"梅花和黄觉民四首 其四","f":"七言绝句","c":["夜来春信到南枝，姑射神人逞雪肌。","多谢长须解予意，送将羁客换新诗。"]},{"t":"梅花和黄觉民四首 其三","f":"七言绝句","c":["依倚春风雨净瓶，暮林摇落避真清。","暗香似与常娥约，来借黄昏淡淡明。"]},{"t":"梅花和黄觉民四首 其二","f":"七言绝句","c":["萧然清映水边枝，似向温泉见玉肌。","被恼诗人应不彻，怪来言语总成诗。"]},{"t":"梅花和黄觉民四首 其一","f":"七言绝句","c":["净几閒窗小小瓶，一枝春色为谁清。","吾今老去心如水，销得诗人与證明。"]},{"t":"绿萼梅","f":"七言绝句","c":["天然腻玉细生香，斜倚东风伫淡妆。","可是春寒犹料峭，晓窗犹试绿罗裳。"]},{"t":"菊","f":"七言绝句","c":["千林摇落见孤芳，色映青松破嫩黄。","玉露凄凉三径晚，金英芬馥几丛香。"]},{"t":"游毛公洞六首 其六","f":"七言绝句","c":["偶因青鸟遂幽寻，翠壁苍崖白日阴。","三扣石扉人不识，满山松竹自悲吟。"]},{"t":"游毛公洞六首 其五","f":"七言绝句","c":["徘徊银穴送斜晖，散遣长须上翠微。","青鸟似知予意确，故传仙语傍人飞。"]},{"t":"游毛公洞六首 其四","f":"七言绝句","c":["山前踊跃见樵人，欲问神仙更问津。","指点长柯向东去，不知银穴又非真。"]},{"t":"游毛公洞六首 其三","f":"七言绝句","c":["须信桃源路易迷，野人遥指过山西。","由来石室非仙窟，漫向云中觅旧蹊。"]},{"t":"游毛公洞六首 其二","f":"七言绝句","c":["旋披荆棘入山来，洞口晴烟翳不开。","试问真人竟何处，他年相就谒蓬莱。"]},{"t":"游毛公洞六首 其一","f":"七言绝句","c":["说诗人去想云车，千古青岩倚碧虚。","训诂未容端拜议，一言聊复问关雎。"]},{"t":"落梅入砚池","f":"七言绝句","c":["玉佩翻然下帝傍，墨池照影妒新妆。","时人莫作飘零看，收拾毫端无尽香。"]},{"t":"谢潘寿卿惠笺并诗","f":"七言绝句","c":["饷厚东阳一万番，从今难放笔头閒。","新诗正与花笺似，文彩纵横咳唾间。"]},{"t":"道上杂花盛开","f":"七言绝句","c":["涓涓流水雨晴初，夹道山花簇綵舆。","千骑不辞迎候远，物情春意竟何如。"]},{"t":"集英殿赐第出马上口占","f":"七言绝句","c":["鞭丝曳雪缭官槐，绿阵中间一道开。","高下未劳轻喜愠，相公曾作榜梢来。"]},{"t":"酬孔纯老送海错三首 其三","f":"七言绝句","c":["恶语岂堪酬妙句，粗餐曾不餍常珍。","得君海错俱奇绝，从此鄞江发兴新。"]},{"t":"酬孔纯老送海错三首 其二","f":"七言绝句","c":["螺头已荷兼三和，凤髓何须贵八珍。","多谢邦君怜不饮，只将诗句巧争新。"]},{"t":"酬孔纯老送海错三首 其一","f":"七言绝句","c":["海错东来自四明，感君怜我故分珍。","拜嘉何必须豪饮，大嚼姑从得句新。"]},{"t":"榴花","f":"七言绝句","c":["看花令我忆金明，五月尊罍竹叶青。","窈窕宝津楼下路，断肠千里四周星。"]},{"t":"题大龙寺","f":"七言绝句","c":["万松邀我上崔嵬，入寺山屏次第开。","无说欲知真说法，松声还送出山来。"]},{"t":"题大泉寺","f":"七言绝句","c":["六峰环翠绕金蓝，下马初尝一酌甘。","久旱喜看云气浃，晚风吹雨过江南。"]},{"t":"题大善寺","f":"七言绝句","c":["絮帽曳丝云带雨，琼梳环髻水围山。","江村五月黄梅过，十里人烟渺莽间。"]},{"t":"题乌江官舍木芙蓉","f":"七言绝句","c":["桃叶萧疏柳叶黄，清寒应怯夜来霜。","芙蓉雅与秋相好，独对层台试晓妆。"]},{"t":"题太湖驿竹轩","f":"七言绝句","c":["粉节储霜竞出篱，我来犹及笋生时。","清风一榻君休问，明月半窗予自知。"]},{"t":"题华严院泽上人西韵轩用前韵","f":"七言绝句","c":["疏帘如雾隐窗纱，虹影青红雨脚斜。","坐久清风起何处，一盆昌歜映葵花。"]},{"t":"题许市施水坊","f":"七言绝句","c":["梦断蓬窗特地愁，卧闻溪水啮船头。","夜航又逐东风去，重叹因人此滞留。"]},{"t":"题许市接待院壁","f":"七言绝句","c":["一檐冬日送清温，疏竹萧萧覆短垣。","来就老僧同曝背，不妨危坐默无言。"]},{"t":"题苦竹寺海棠洞三首 其三","f":"七言绝句","c":["一径封苔知雨足，贰车行县昔时迁。","对花啜茗思春日，拂拭新诗益怅然。"]},{"t":"题苦竹寺海棠洞三首 其二","f":"七言绝句","c":["隔夜西风为办严，扫除氛曀出晴天。","正逢翠幄张青绮，应念朱唇拂紫绵。"]},{"t":"题苦竹寺海棠洞三首 其一","f":"七言绝句","c":["翠袖朱唇一笑开，依风无力竞相隈。","阳城岂是僧家物，端恐齐奴步障来。"]},{"t":"题南巢地藏寺","f":"七言绝句","c":["蚊觜生花夜更长，睡乡蝴蝶正悠飏。","山僧不恤秋眠熟，连打钟声到枕旁。"]},{"t":"题宿松薤山寺","f":"七言绝句","c":["小驿隳颓不见容，著鞭东走梵王宫。","怪禽落日休相恐，五里松篁一径通。"]},{"t":"题崇因院清轩","f":"七言绝句","c":["肥松瘦竹古招提，轩槛重游识旧题。","清意不曾吟得尽，夜来明月浸寒溪。"]},{"t":"题德山涓老无句堂","f":"七言绝句","c":["峰头示众合如何，一棒由来已自多。","空去空回还信否，至今疑杀那人诃。"]},{"t":"题德章山","f":"七言绝句","c":["丛玕泼黛千峰色，急雨奔霆万壑声。","莫讶祖师来入梦，祇应知我欲山行。"]},{"t":"题德章山亲公塔","f":"七言绝句","c":["凭陵风雨上崔嵬，一见亲公病眼开。","似是前生师弟子，两年今日入山来。"]},{"t":"赠林山善相老荣师","f":"七言绝句","c":["至哉择术妙难论，邂逅何妨丐一言。","我已无心求富贵，馀生归命给孤园。"]},{"t":"赠桐林老僧","f":"七言绝句","c":["绕屋青桐碧玉椽，坐来岩石起云烟。","过门竟日奔驰者，应羡山僧去道边。"]},{"t":"赠浮屠道本二首 其二","f":"七言绝句","c":["一去禅关忽五春，异乡惊见眼终清。","问师参学今何解，云在青天水在瓶。"]},{"t":"赠浮屠道本二首 其一","f":"七言绝句","c":["暑雨初晴江上村，藕花无数午风温。","梁山正帖淮南岸，到得精蓝日未昏。"]},{"t":"赠道上人","f":"七言绝句","c":["道人知我过山来，旋扫蓬门对水开。","惟有温菘荐樽俎，一畦疏绿隐蒿莱。"]},{"t":"赠蔡道人","f":"七言绝句","c":["宝盖山前蔡道人，十年学佛颇安贫。","似闻亲见天衣老，为改今名作惠新。"]},{"t":"上巳日阻雨和王冲之韵","f":"七言律诗","c":["韨除聊复对江亭，樽酒相从一笑倾。","那得此时仍此乐，况逢难弟与难兄。","潺潺暮雨檐间溜，滑滑春泥柳外声。","好在海棠红閤泪，向人悽怆益多情。"]},{"t":"久客和子薳用老杜韵","f":"五言律诗","c":["舟解风还顺，江神亦世情。","滞留三月过，攀送一帆轻。","行止关吾道，穷通任此生。","梅梢春已动，冰雪漫纵横。"]},{"t":"广济道中","f":"五言律诗","c":["晓日挂林麓，秋风入涧阿。","野禽飞自语，田父笑相过。","村疃仓箱富，山蹊芋栗多。","一鞭聊策蹇，驰上小罗坡。"]},{"t":"中秋 其一","f":"五言律诗","c":["静院三更雨，楼台一点风。","新诗愁恨里，故国梦魂中。","节物它乡异，交情我辈同。","眼前多怪事，咄咄强书空。"]},{"t":"中秋 其二","f":"五言律诗","c":["出户喜折屐，江天来翠岑。","看云忘久立，待月动微吟。","关塞重回首，简编劳系心。","琴中有山水，应解遇知音。"]},{"t":"中秋和彦立兄韵悼伯父仲球","f":"七言律诗","c":["月华秋气共清圆，千古佳时句一联。","节物伤心还惙惙，山光经雨自涓涓。","潢池兵火今方炽，沟壑饥羸正可怜。","怊怅去年人已矣，乱离谁复问招延。"]},{"t":"丹阳湖阻风二首 其二","f":"五言律诗","c":["老去心犹壮，诗成喜欲颠。","时危思报主，穷极待呼天。","归梦先湖外，离情到酒边。","晚来风更恶，舟卧不成眠。"]},{"t":"丹阳湖阻风二首 其一","f":"五言律诗","c":["水阔风还怒，舟轻浪更颠。","云容初过雨，湖势欲吞天。","沙觜青枫外，鱼罾白鸟边。","夕阳应到岸，沉醉酒家眠。"]},{"t":"为兴国周少隐题","f":"七言律诗","c":["紫翠森攒面面山，个中佳致为君还。","凭阑人在风尘表，落纸诗成咳唾间。","良夜幸陪红袖醉，清时聊伴白鸥閒。","笼纱归去高城晚，凝翠堂东月满湾。"]},{"t":"为彭积甫题熙春堂","f":"七言律诗","c":["似闻伐石旋诛茅，已见高堂荫乐郊。","百里湖山供眼界，满城桃李动春梢。","寒梅过尽看成实，乳燕飞来欲定巢。","何日登临閒信马，路边人复少年嘲。"]},{"t":"历阳倅蒙庵郑公卒于位记岁在丁丑与仆有交承之契方来自镇西而仆亦自安丰往邂逅于合肥驿中获为三日之款所谈无非周易太玄老庄之书开警蒙昧多矣公平生学佛行一着端的不昧所谓毫发无遗恨者仆老矣请从其后而为净土之游似不晚也作是诗以吊之 其二","f":"五言律诗","c":["东晋陶元亮，西京董仲舒。","高风敦薄俗，妙论见遗书。","水石伤新窆，松篁惨旧庐。","楞伽今在否，此道发明初。"]},{"t":"历阳倅蒙庵郑公卒于位记岁在丁丑与仆有交承之契方来自镇西而仆亦自安丰往邂逅于合肥驿中获为三日之款所谈无非周易太玄老庄之书开警蒙昧多矣公平生学佛行一着端的不昧所谓毫发无遗恨者仆老矣请从其后而为净土之游似不晚也作是诗以吊之 其一","f":"五言律诗","c":["我倅安丰日，君来自历阳。","交承分彼此，邂逅及行藏。","精义通玄易，微言妙老庄。","刹那今十稔，叹仰未能忘。"]},{"t":"历阳寄定城尉彦逢弟","f":"七言律诗","c":["故园鹎鵊久催耕，休恋公田秫与粳。","别恨久随黄耳去，归心应望白云生。","干戈丛里三书考，春夏交来几闭城。","我亦蓝田负丞者，相从何日赋渊明。"]},{"t":"太湖呈邵公晋沈元吉","f":"五言律诗","c":["半月江湖上，晚来方得风。","挂帆谁共快，到岸偶相逢。","可是过从旧，都缘臭味同。","长亭一樽茗，亲厚意何穷。"]},{"t":"长至和魏公达","f":"七言律诗","c":["半夜迎长坐候明，眼看初日屋山平。","诗豪不共年俱长，鬓雪惟应老自生。","得酒人情何太喜，犯寒春色不多争。","老农相庆无它语，尽道冬晴好趁耕。"]},{"t":"东灵鹫","f":"五言律诗","c":["松盖雨还偃，云扉风自关。","纵横两溪水，高下万重山。","入室三弹指，临渊一点颜。","悬知少来往，石笋绿苔斑。"]},{"t":"代人上段拂参政","f":"七言律诗","c":["玉牒书成已六年，东游曾记此周旋。","千龄令庆亨嘉会，二府新分造化权。","咫尺云天依日月，斯须霖雨浃山川。","应怜汨没尘埃者，白发青衫走道边。"]},{"t":"冬夜对月怀彦逢弟","f":"五言律诗","c":["荒庭寒有月，穷巷静无声。","坐想积年别，遥同今夕明。","蹉跎前进士，憔悴老书生。","短棹归来好，边城久偃兵。"]},{"t":"对雪和马大卿","f":"七言律诗","c":["投分江梅亦太清，寻盟风絮却多情。","势先泽腹归冰鉴，气迫毫尖入管城。","吏部梦踰秦岭去，将军来作蔡州行。","拥炉令我思前躅，策蹇高吟愧孟生。"]},{"t":"对雪和因老韵","f":"七言律诗","c":["谏陛何人正伏蒲，将坛无事且投壶。","因观雪曲词争胜，便觉诗邻势不孤。","警雁王师方入蔡，赠梅边使欲离吴。","可怜鼠辈殊轻敌，乃敢堂堂捋虎须。"]},{"t":"归自合肥于四顶山绝湖呈孙仁叔抑之","f":"五言律诗","c":["达岸三时顷，瞻山四顶赊。","乔林知马尾，乱石见獐牙。","水脚浮青靛，湖唇滉白沙。","渔人收辏网，归去日西斜。"]},{"t":"用东坡赠晁新城韵呈朱乌江","f":"七言律诗","c":["偶然来赋瓦梁行，乱后欣闻醉客声。","村戍火明人指路，江城风静夜鸣钲。","对床听雨他时念，拨火哦诗此意清。","闻说鱼轩还枳里，先生应合暂归耕。"]},{"t":"用李梦发韵","f":"七言律诗","c":["梦回诗思不胜清，卧听幽禽两啭更。","窗角界金分月色，山腰鸣玉漱溪声。","欲行且住心还适，久雨新晴眼倍明。","莫为浮名废真赏，较来何重亦何轻。"]},{"t":"用陈阜卿劝农韵呈宣城太守 其二","f":"五言律诗","c":["欲知人意喜，万户郁炉烟。","纱帽花垂额，金卮酒到莲。","岁丰端可卜，农劝竞相传。","往矣南阳政，今追召父贤。"]},{"t":"用陈阜卿劝农韵呈宣城太守 其一","f":"五言律诗","c":["何处催耕早，宣城刺史先。","旗麾明晓市，耒耜遍晴川。","道路欢声接，樽罍丽景鲜。","似闻携百榼，分饷及高年。"]},{"t":"田间夜归有作示王觉民二首 其二","f":"七言律诗","c":["江上秋来忆少牢，龟肠尤觉病诗饕。","调和索似三分酱，澒洞看如八斗糟。","水怪重增风势恶，湘灵难禁雁声高。","何当一雨洗烟月，为放清光归我曹。"]},{"t":"田间夜归有作示王觉民二首 其一","f":"七言律诗","c":["风云踪迹付扁舟，水竹生涯寄一丘。","世故举同鸡抱鸭，物情无怪马生牛。","百年半向愁中老，万事常从酒到休。","莫爱得官轻得句，争如饱食对吟搜。"]},{"t":"示隐静恭老","f":"七言律诗","c":["游山何敢避泥涂，恰值催花夜雨馀。","杯渡已知无用楫，马行今信不更车。","数声幽鸟过庭际，一派飞泉赴壑初。","正欲寻师问心法，却惊行色逼钟鱼。"]},{"t":"立春小酌呈诸兄","f":"七言律诗","c":["共喜春随晓色来，东郊欢踊赛牛回。","破寒青转芜菁叶，抵日红抽芍药荄。","岁换未劳惊我壮，酒封聊复为君开。","上林不负迁乔约，百蛰同惊此夜雷。"]},{"t":"立春日雪和赵端质韵","f":"七言律诗","c":["春寒有信不踰期，肯为衰颜独见欺。","白雪已输梅斗早，绿樽尤与火相宜。","撷来野蔌和萱草，分得江鱼贯柳枝。","刺史忧民民共乐，赛牛归去竞褰帷。"]},{"t":"立春示儿二首 其一","f":"五言律诗","c":["雪尽适沾雨，腊穷初得春。","上冰鱼意乐，出谷鸟声新。","便觉风光好，何忧活计贫。","一樽聊共醉，疏率见吾真。"]},{"t":"立春示儿二首 其二","f":"五言律诗","c":["朝来何所喜，人唱玉楼春。","酒著心还壮，诗成思转新。","士衡宁久困，曲逆岂长贫。","千载风云会，欣逢圣主真。"]},{"t":"立春和孙子绍二首 其二","f":"五言律诗","c":["南浦初开冻，东郊未去寒。","芳华归草木，生意入门阑。","绿蚁供瑶瓮，青丝送玉盘。","新诗妙当世，赋答敢辞难。"]},{"t":"立春和孙子绍二首 其一","f":"五言律诗","c":["老穷推不去，湖海又逢春。","懒复论三甲，空惊荐五辛。","柳梢寒已动，萱草暖还新。","我亦寰中物，因君试问津。"]},{"t":"边公式周表卿侍郎同年会","f":"七言律诗","c":["侍郎修好燕群公，雁塔题名二纪同。","谈笑静移杨柳日，杯盘清泛芰荷风。","鹏抟竞祝三旌贵，鲸吸相期百榼空。","此会明年应更好，马周行亦起新丰。"]},{"t":"伏蒙知县县尉二寮友以夏旱得雨赓石徂徕喜雨韵见贶不可虚辱复嗣其韵书谢仍命儿曹同赋","f":"七言律诗","c":["绿槐阴外听蝉吟，节过分龙夏已深。","千里亢阳忧岁旱，一时甘雨快人心。","养禾不害连朝曀，沃暑应容数日霖。","多谢同寮怜老拙，双南佳句竞铿金。"]},{"t":"再和董令升雪二首 其二","f":"七言律诗","c":["欲下閒庭不蹋泥，但惊飞絮与阶齐。","一枝误失禽栖稳，三窟遥应兔迹迷。","填塞涧溪还地厚，壅培山阜觉天低。","寒光照应东窗白，咿喔应先报晓鸡。"]},{"t":"再和董令升雪二首 其一","f":"七言律诗","c":["春雪初融作燕泥，梅花零落杏花齐。","遥山扫翠云初敛，芳草铺青路欲迷。","别恨每忧儿辈觉，老怀终为世情低。","新诗价重连城壁，敢比灵犀独骇鸡。"]},{"t":"因上人访予相山夜闻二子诵书有诗次韵","f":"七言律诗","c":["杖锡东来意亦勤，寒岩枯木自相亲。","方惊妙论雨侵坐，忽喜新诗光照人。","物外交游清似水，梦中忧患碎如尘。","儿童正欲承砻错，应觉临文便有神。"]},{"t":"次方正叔知县韵仆今年六十有三窃观正叔赠陈甥述怀诗有感予心并和二首奉呈 其二","f":"七言律诗","c":["水满陂塘麦满村，路逢田父和长言。","题诗懒作蝇头字，贳酒愁看犊鼻裈。","芳草藉青迷野径，远山横翠入柴门。","道衡骨朽无人继，卿相谁能预识温。"]},{"t":"次方正叔知县韵仆今年六十有三窃观正叔赠陈甥述怀诗有感予心并和二首奉呈 其一","f":"七言律诗","c":["年踰六十我何堪，心曲因君得纵谈。","阅史旧尝疑夏五，参禅今遂荐前三。","饮阑却怪清樽恶，饥甚犹怜粝食甘。","交态物情何足较，迩来炉鼎兴方酣。"]},{"t":"次因上人韵","f":"五言律诗","c":["一从潜水别，三见菊花黄。","旧好论交笃，新诗引兴长。","劳生閒自笑，道术淡相忘。","蝴蝶秋来懒，时应到睡乡。"]},{"t":"次彦时兄苦旱韵","f":"七言律诗","c":["斗粟衡门且自安，老来筋力厌辛酸。","官游动是三年别，邂逅应容一笑欢。","荷浦珠联秋露溢，稻田龟坼暑风乾。","昨朝溪足捎新雨，已觉羸躯怯夜寒。"]},{"t":"次韵元发弟秋日德馀庵书事二首 其二","f":"七言律诗","c":["十载江湖叹断蓬，梦魂时到帝王宫。","珠帘高捲虾须日，宝扇斜开雉尾宫。","勿诮赵尧刀笔吏，须怜窦巩嗫嚅翁。","儿童来告黄花熟，可喜樽中酒不空。"]},{"t":"次韵元发弟秋日德馀庵书事二首 其一","f":"七言律诗","c":["饱谙世事转疏慵，投老犹能向佛宫。","危坐遂移桑荫日，清谈仍对菊花风。","凭君为我追欢伯，自此游山作醉翁。","闻说秋来足佳句，暮归应念锦囊空。"]},{"t":"次韵同舍李支使梦与二首 其二","f":"七言律诗","c":["短短灯檠便且光，看书犹记感秋凉。","飘零未遂襟期远，迟暮徒惊岁月伤。","初喜嫩荷青直盖，不知新竹粉储霜。","相从益觉交情笃，时掷隋珠到我行。"]},{"t":"次韵同舍李支使梦与二首 其一","f":"七言律诗","c":["三纪桥门过隙光，醉吟曾共晚风凉。","旧游何在已芜没，前好欲言空感伤。","重对诗囊开锦绣，要看谈麈落冰霜。","苕溪此去如相忆，双鲤时应寄一行。"]},{"t":"次韵因上人谢徐守遗顾渚茶","f":"七言律诗","c":["相从聊罢致书邮，情寄诗筒早晚休。","顾我未忘童子好，评君还向古人求。","缃奁启处云英馥，石鼎煎来雪浪浮。","多谢徐卿分顾渚，报之琼玖两相收。"]},{"t":"次韵孙兴宗梅花","f":"七言律诗","c":["厌浥庭柯雨未乾，乍晴天气午犹寒。","传来多谢新诗寄，接得翻愁病眼看。","漫想素妆嫌粉涴，须怜青子着枝酸。","和羹有日君知否，老大心肠只自宽。"]},{"t":"次韵伯远运干见寄","f":"七言律诗","c":["善邻虽幸借馀光，终愧陈臻问发棠。","官柳又惊眉拂翠，宫梅应喜额涂黄。","江湖得计还相造，道义论交付两忘。","多谢乾坤容长物，许乘春意到文昌。"]},{"t":"次韵何子应大卿喜雪武昌作","f":"七言律诗","c":["云气浮江不见边，拥炉吟雪思飘然。","风将急霰先鸣瓦，水剪寒花忽际天。","才涩敢陪梁苑客，兴来从泛剡溪船。","将军乘夜平淮蔡，翻笑元和十二年。"]},{"t":"次韵张进彦见寄二首 其二","f":"七言律诗","c":["鼻息齁齁尽日眠，从他儿辈竞嘲边。","那知问对成中说，自得逍遥喜内篇。","雪里书来檐噪鹊，灯前诗就鼎凝烟。","中郎去后人难继，漫诧柯亭富笛椽。"]},{"t":"次韵张进彦见寄二首 其一","f":"七言律诗","c":["坐想云烟走笔端，夜哦佳制老忘寒。","一时思致追长庆，千载风流识建安。","接武尚稽班玉笋，昂霄终合待金銮。","自怜衰退无新语，捧腹还君醉眼看。"]},{"t":"次韵沈元吉兵火后初食羊","f":"七言律诗","c":["时难盆甑久无膻，梦寐何郎食万钱。","一脔乍惊肥羜美，五紽应喜敝裘全。","好从牛炙论莼菜，堪笑河鲀咏柳绵。","弹铗得鱼良不恶，先生何用鄙烹鲜。"]},{"t":"次韵周子嘉咏雪","f":"七言律诗","c":["势凌风力斗清严，彻骨尤非老病堪。","冻蠡夜回千首北，寒梅朝放一枝南。","扁舟底事方行役，贩履何人正立谈。","江上别来劳梦寐，相宽犹喜见诗三。"]},{"t":"次韵周运判彦约芍药","f":"七言律诗","c":["独殿群芳占晚春，对花犹幸有斯人。","宓妃正自须曹赋，楚女何妨与宋邻。","醉著午风浓似酒，妆融朝雨细如尘。","边城正藉诗书帅，俎豆于今识祭遵。"]},{"t":"次韵周漕喜雨","f":"七言律诗","c":["十载栖迟畎亩间，无聊尤苦屡无年。","可怜一雨今时若，便觉千塍顿郁然。","击壤有期应共庆，效颦非分敢争妍。","正当檐溜江河决，想见高吟夜不眠。"]},{"t":"次韵徐伯远木芙蓉","f":"七言律诗","c":["千林摇落见孤芳，销得诗人赋拒霜。","高压菊花还独步，静窥池水试新妆。","自怜衰病追欢懒，忽睹骚吟引兴长。","何必采江重比并，佳名艳色正相当。"]},{"t":"次韵秦寿之题四祖","f":"七言律诗","c":["古木参天翠作堆，云中石栈为谁开。","楼台正倚双峰起，香火曾瞻四祖来。","霜重静闻秋子落，风高愁听晓猿哀。","当年松上花何似，五叶依然映紫苔。"]},{"t":"次韵程德远登清淮楼","f":"七言律诗","c":["西望中原懒转头，十年空见水东流。","涂山漫想诸侯会，濠上聊追二子游。","大剑长刀秋正扰，淡烟疏雨暮还愁。","谁能不讨清河朔，誓楫当期祖豫州。"]},{"t":"次韵董令升梅花","f":"七言律诗","c":["花前樽酒泻尖泥，痛饮仍欣客到齐。","竹外一枝青更好，水边疏影动还迷。","醉醒正值微风入，酬唱何妨素魄低。","闻说归舟阳羡去，应容酌别为烹鸡。"]},{"t":"次韵蒋守张进彦","f":"七言律诗","c":["邂逅传杯莫放杯，七年重见梦初回。","休嗟岁月堂堂去，且喜旌麾得得来。","春至会沾新雨露，时清应扫旧氛埃。","如君才业今张镐，怜我栖迟毂屡推。"]},{"t":"次韵鲁如晦七夕","f":"五言律诗","c":["今夕知何夕，相逢莫漫愁。","凉飔开北牖，新月挂西楼。","重惜经年别，贪延数刻秋。","明朝河汉隔，西向望牵牛。"]},{"t":"次韵蔡永叔双头芍药","f":"七言律诗","c":["反复新诗对月华，视模犹及正而葩。","坐驰芍药心先醉，身老江湖眼欲花。","夜半已酬连理约，风前还见一枝斜。","滩头更下双鸂鶒，并与妖红作意誇。"]},{"t":"江南道中","f":"七言律诗","c":["江回山崦两三家，招飐东风酒旆斜。","羸马送曛行自急，峭寒欺客晚还加。","日边雁足应传信，竹外梅梢合放花。","指点东城归路窎，一川流水闹栖鸦。"]},{"t":"舟过三丫河","f":"五言律诗","c":["摇落蒹葭浦，荒凉雁鹜村。","吴柑迎齿冷，鲁酒著颜温。","水涩风还逆，天寒日自暾。","不堪归思乱，鸟鹊闹黄昏。"]},{"t":"过邓步和张叔元见赠韵","f":"七言律诗","c":["独舸东来夏日长，归装从此益生光。","卧云禾穗珠成实，倾露荷花麝被囊。","逸世才猷金騕袅，逼人风味木兰堂。","常疑正始遗音绝，把读新诗远坛场。"]},{"t":"丽泽堂","f":"七言律诗","c":["焚香读易欲何求，只恐西邻未识丘。","千里交游思命驾，一龛灯火喜逢秋。","胸中云梦应无算，天上风雷得遍搜。","莫向明时老岩壑，伊周元不羡巢由。"]},{"t":"吴兴舟中有作","f":"五言律诗","c":["大泽知何处，扁舟快此行。","绮罗纷胜赏，歌吹溢欢声。","茭葑春还合，波涛暮自平。","临风一披拂，谁识未归情。"]},{"t":"呈蔡元德二首 其二","f":"五言律诗","c":["一叶黄梅雨，潺潺过麦秋。","昏沉浑似醉，憔悴不禁愁。","渠溢门庭淖，园荒草树稠。","乍晴酬绝唱，何幸对风猷。"]},{"t":"呈蔡元德二首 其一","f":"五言律诗","c":["别来閒计日，一日似三秋。","顾我无能老，逢君始欲愁。","诗情今转胜，交契久还稠。","学问神龟似，当年继践猷。"]},{"t":"弟子厚自相山徙居湖塘又复一月矣距外除只数日间光景漂流徒成感慨读新诗兴不能已辄和韵","f":"七言律诗","c":["相逢休访楚江萍，我老无能一壮丁。","卜宅又惊三浃日，御琴空感再周星。","新愁卯酒心先醉，气怯春寒梦易醒。","却喜故山遥在眼，举头时见竹青青。"]},{"t":"沙窝道中","f":"五言律诗","c":["十里沙窝路，晴云向暮开。","褰裳九过水，驻马一观梅。","岁晚松篁茂，山寒虎豹哀。","不因王事迫，谁肯此间来。"]},{"t":"苏台悯农","f":"七言律诗","c":["稻田高下欲分畦，积潦瀰茫隔寸堤。","天意未收连夜雨，农功良苦半身泥。","一丸莫救风涛决，千顷空怜稼穑低。","朝满夕除应可信，望晴心绪忆昌黎。"]},{"t":"还通上人卷","f":"七言律诗","c":["格清词苦与谁论，携绕钱塘给事坟。","所得岂容人继和，朗吟应被鹤听闻。","月轮冷照千岩雪，霞片轻装万叠云。","投向吾庐卜知己，拟将诗草为师焚。"]},{"t":"閒居","f":"五言律诗","c":["五斗不尔竞，一区聊自营。","閒看探花信，静坐听松声。","约客酒初熟，访僧诗漫成。","有时过闾里，往往竞邀迎。"]},{"t":"閒眠","f":"五言律诗","c":["乍暖经行久，新凉出浴初。","酒酣春昼永，食饱午钟馀。","我懒喜聊复，君閒应乐胥。","年来苦奔走，此味竟何如。"]},{"t":"和丁景仁三叉河留题赠李仲山","f":"七言律诗","c":["飘零双鬓已星星，万里江湖寄此身。","山拥青螺初洗雨，水浮苍壁似围春。","别来兴废同千古，此去荣枯会一新。","葭薍弥天草如积，宽予犹赖有斯人。"]},{"t":"和子薳泛江送客用老杜韵","f":"五言律诗","c":["北风还入夜，波怒未能平。","江气云烟重，山光水墨轻。","荧荧渔火乱，惨惨暮寒生。","咫尺淮乡路，淹留系此情。"]},{"t":"和子薳官牌夹口韵是日闻官军破虔贼","f":"五言律诗","c":["滞留嗟是役，艰险笑吾生。","此去和风顺，朝来虔贼平。","湖山争喜气，雁鹜送欢声。","千里前塘路，应知客念轻。"]},{"t":"和子薳春江用老杜韵","f":"五言律诗","c":["欲去未成去，朔风鸣怒涛。","片帆洲外举，列岫雾中高。","竹屋雨沾被，纸窗寒透袍。","遥应望归艇，向夕走儿曹。"]},{"t":"和历阳李簿见寄","f":"五言律诗","c":["短鬓纷垂白，衰颜悴带黄。","多寒冬更甚，少睡夜能长。","旧学长荒废，新知感爱忘。","何时一樽酒，谈咏带江乡。"]},{"t":"和天宁因上人次韵","f":"七言律诗","c":["日月漂流一鸟过，别来心迹病维摩。","是非孰辨聊分谤，诞信相讥要止讹。","摇落独怜松不改，澄清尝见海无波。","句中有眼劳开警，更问诸人会得么。"]},{"t":"和孔纯老归自属邑三首 其三","f":"七言律诗","c":["诗涛难放笔头乾，归及初晴素魄圆。","善誉敢论当世比，佳萹应任老夫传。","凌云列岫堆螺髻，出水新荷点翠钿。","报政还朝知不晚，追随能复记当年。"]},{"t":"和孔纯老归自属邑三首 其二","f":"七言律诗","c":["往来阴雨恰弥旬，滑滑那堪鸟语频。","行色可无三日霁，旅怀应付万家春。","欣闻郊劳开瑶席，想见车旋入锦茵。","何幸诗筒时寄我，慰怀须信有诗人。"]},{"t":"和孔纯老归自属邑三首 其一","f":"七言律诗","c":["行县归来赋陟冈，青梅应快一樽尝。","诗成妙墨挥张圣，酒到高歌发楚狂。","夹道野花围步障，两行官妓簇桥梁。","嗟予贫悴跧蓬荜，不及郊迎笑举觞。"]},{"t":"和孔纯老按属邑二首 其二","f":"七言律诗","c":["杨柳依依半掩扉，新晴疏影弄斜晖。","好花觅句忍轻负，幽鸟劝沽良重违。","閒爱青苔缘砌上，静看蝴蝶扑窗飞。","雨多不觉芜菁过，又喜盘中笋蕨肥。"]},{"t":"和孔纯老按属邑二首 其一","f":"七言律诗","c":["高车西去忽踰旬，坐想登临得句频。","杨柳阴交山径晚，酴醾香满驿亭春。","吟馀扫壁时挥翰，醉里投床任吐茵。","闻说归来欢喜甚，故人相遇是诗人。"]},{"t":"和孔纯老送司法吴德声","f":"七言律诗","c":["舞腰回雪奏伊凉，饯设铃齐举别觞。","如子固宜倾坐客，顾予何计挽征艎。","交情旧喜推东道，归梦先应到北堂。","花柳枝头春已闹，伫观超擢寘周行。"]},{"t":"和文倅侯彦嘉二首 其二","f":"七言律诗","c":["晖晖晴日树头平，望外遥山宿雾轻。","积潦夜增南浦涨，微风朝送北窗清。","滞留羁客牵归思，陶写新诗尽物情。","谁谓春宵常苦短，老来无寐厌长更。"]},{"t":"和文倅侯彦嘉二首 其一","f":"七言律诗","c":["相逢珠玉走佳章，顾我无能更老苍。","尝鼎固应从指染，冲天行喜见云翔。","向来别恨江同远，此去诗情日共长。","才似二公今二妙，山庭渊角绣肝肠。"]},{"t":"和方正叔芍药","f":"七言律诗","c":["院落青和昼漏长，曲栏高槛倚新妆。","未饶玉蕊来仙女，那羡莲花似阿郎。","遣兴勉从吾辈在，追欢难入少年场。","开缄忽得惊人句，满纸云烟翰墨香。"]},{"t":"和方景南参议见赠","f":"七言律诗","c":["向来疏率任天真，此去扶持护善邻。","只恐磨砖难作镜，已知行水戒推轮。","箪瓢本是吾家物，轩冕宁容我辈人。","多谢诸公共推毂，欣欣寒谷暗生春。"]},{"t":"和王冲之喜雨呈张文伯","f":"七言律诗","c":["指点邦人著眼看，鲁侯雩祭正玄端。","望来已见千山雨，此去那忧百谷乾。","高廪有期从穧敛，奔霆何处起龙蟠。","新诗得得书灵应，传与群公好纵观。"]},{"t":"和王觉民简褒山因上人枣岭魏欣然二首 其二","f":"五言律诗","c":["君来踰半月，未果一尊同。","湖水寒应碧，山梨雨自红。","何时过北牗，今日转西风。","相去无他地，孤城杖屦中。"]},{"t":"和王觉民简褒山因上人枣岭魏欣然二首 其一","f":"五言律诗","c":["七行才业在，宁久困无津。","秋到搏风翼，春回纵壑鳞。","褒山方竞秀，枣岭益争新。","珍重二三子，诗骚追古人。"]},{"t":"和刘与可二首 其二","f":"五言律诗","c":["野塘春草遍，芳树老藤缠。","远信占黄耳，清游任白颠。","山光晴抹黛，湖气暖腾烟。","我有边韶癖，何妨昼日眠。"]},{"t":"和刘与可二首 其一","f":"五言律诗","c":["老来无柰懒，春至不胜情。","万石嗟遗迹，双鱼谢寄声。","压花朝雨重，酾酒夜泉鸣。","细把君诗读，冰壶表里清。"]},{"t":"和因上人三首 其三","f":"七言律诗","c":["白云飞处是吾家，石眼泠泠水一车。","醉日到来应种竹，梅时过尽好藏茶。","遥怜壶枣初成实，似说占禾半吐花。","已得伽陀微妙句，归欤香火讽啰耶。"]},{"t":"和因上人三首 其二","f":"七言律诗","c":["归骑何时遂到家，苍头猎猎走风车。","丑妻终胜长为客，薄酒能无更饮茶。","梦断北窗凉似水，望中南亩雨飞花。","采莲游女应相识，早晚扁舟访若耶。"]},{"t":"和因上人三首 其一","f":"七言律诗","c":["一抨兰若复谁家，坐见羲和下日车。","燥吻未濡莲社酒，枯肠空搅玉川茶。","摇风绿竹初翻箨，过雨红葵甚放花。","得句至今频示我，安能郁郁久兹耶。"]},{"t":"和因格非见寄二首 其二","f":"五言律诗","c":["兀坐时看屋，閒居昼掩门。","吴吟聊遣兴，楚些欲招魂。","否泰宜周易，行藏付鲁论。","不须伤老大，眠食度朝昏。"]},{"t":"和因格非见寄二首 其一","f":"五言律诗","c":["青山如我约，终日对柴门。","学道未忘念，怀君空断魂。","时来当有用，事往置无论。","反覆新诗读，谁知老眼昏。"]},{"t":"和孙延寿喜雨述怀韵","f":"七言律诗","c":["小雨霏霏夜接朝，乍惊和气入民谣。","官逋庶为麦秋缓，酒价定随人意饶。","欲落枣花蚕断茧，半黄梅子稻移苗。","书生不惯征徭苦，牢落僧房不自聊。"]},{"t":"和州得旨移粟宣城舟中和何希渊韵","f":"七言律诗","c":["辙鱼应怪决江流，千里重为叠嶂游。","颇惯黑甜相对美，可无赤糙为宽忧。","干戈在眼心还折，勋业何时鬓早秋。","已办卖刀归买犊，不妨多种白江州。"]},{"t":"和巩兴宗题回峰寺赠明山主","f":"五言律诗","c":["江共烟云远，山连薮泽长。","日从三伏烈，风借九秋凉。","休作桃花观，聊同柏子香。","相逢无一事，不必下禅床。"]},{"t":"和江和仲","f":"七言律诗","c":["把读新诗忆旧家，深村羸犊短辕车。","年丰野老常携酒，客至幽禽自唤茶。","乱后所存惟五柳，老来无意约山花。","相逢何必曾相识，乘兴时来过此耶。"]},{"t":"和许端夫兄弟二首时端夫出守当涂 其一","f":"七言律诗","c":["灯火当年记马行，一时人物玩垂裳。","旧游乱后半芜没，新贵迩来多罪亡。","我有埙篪相应和，君同兰玉竞芬芳。","高文已见含元赋，不用研思古战场。"]},{"t":"和许端夫兄弟二首时端夫出守当涂 其二","f":"七言律诗","c":["相喜何须日寄声，如君无处不知名。","纵观妙墨云烟动，想见新诗欬唾成。","带雪山川增绮丽，向春梅柳自欣荣。","好将十咏图归去，稳步花砖继李程。"]},{"t":"和伯父仲球立春即事二首 其二","f":"七言律诗","c":["对雪酬春付酒杯，兵馀真似复然灰。","路通千里传书去，人喜三军破贼回。","梅萼封檀香未彻，湖声撞玉冻初开。","疏篱败屋休兴叹，幸事群凶不再来。"]},{"t":"和伯父仲球立春即事二首 其一","f":"七言律诗","c":["怪得青腰稍霁威，却应缇室报飞灰。","摇风柳带缘冰重，破冻溪流与岸回。","群盗传闻湖外去，愁云准拟岁前开。","玉盘丝菜今萧索，赖有诗筒日往来。"]},{"t":"和余元明时元明邀余同李次元夜饮","f":"七言律诗","c":["坐中强半是同年，赖有斯人席更圆。","跨马未须贪远道，举觞聊复望青天。","枯荷折苇三墩路，明月清风百丈船。","俯仰便成陈迹恨，须知此集不论钱。"]},{"t":"和余时中元夕二首 其二","f":"五言律诗","c":["罗绮行歌夜，杯盘坐笑春。","舞衫催急管，步障拥佳人。","灯火珠星粲，楼台璧月新。","传柑良可乐，黼座玉音亲。"]},{"t":"和余时中元夕二首 其一","f":"五言律诗","c":["今夕知何夕，熙熙万室春。","歌楼醒醉客，灯市往来人。","劝酒行杯促，联诗得句新。","铜壶休见迫，欢笑正相亲。"]},{"t":"和应资深九日游康乐园二首 其二","f":"七言律诗","c":["里社安閒得久生，金华端不羡初平。","山林应有清修重，轩冕还将道义轻。","诗捷口占那复藁，酒豪盆酌不论觥。","一斑已幸窥秋句，囷廪他时冀倒倾。"]},{"t":"和应资深九日游康乐园二首 其一","f":"七言律诗","c":["村落潇潇晚吹生，斜阳天际与林平。","黄花照眼吟肩耸，红袖扶头醉帽轻。","可惯探题仍击钵，敢辞偿令独浮觥。","相逢又复惊相别，樽酒何妨意气倾。"]},{"t":"和张元礼","f":"七言律诗","c":["力学三年看有成，龙蛇蟠蛰冀存身。","一杯饯别初迎腊，千里归来欲送春。","爱日光阴宜共惜，及时德业要争新。","吾家丛桂风流在，速取高科慰老亲。"]},{"t":"和张公仪","f":"七言律诗","c":["醉中行草绾秋蛇，十载风棂忆旧家。","朋旧乱多从鬼录，诗书閒益富生涯。","稻塍绿合迷秧马，沙嘴潮回下钓车。","归去西畴新雨足，饭粳应不羡胡麻。"]},{"t":"和张文纪咏雪二首 其二","f":"七言律诗","c":["朝来经阁课楞严，撩乱飞花竞扑帘。","似是青腰誇黑帝，故教姑射混无盐。","地炉无奈貂裘薄，斗酒难供座客添。","诗债恼人眠不得，夜寒残管亦须拈。"]},{"t":"和张文纪咏雪二首 其一","f":"七言律诗","c":["万境沉沉夜气严，广寒初下水晶帘。","三杯强沃浇肠酒，一捻聊分暖砚盐。","已恨梅梢遭挫折，可堪风物为般添。","才高柳絮虽难到，此语于今亦恶拈。"]},{"t":"和张安国舍人","f":"七言律诗","c":["判花西掖妙当年，曾见声华振日边。","文翰共推唐李峤，功名将踵汉韦贤。","江山到处供诗笥，风月多情付酒船。","琳馆正应聊尔耳，会看鹏击水三千。"]},{"t":"和张序臣合肥驿中诗","f":"七言律诗","c":["橐皋何处合肥东，知有诗翁杖履中。","鲁会一时归寂寞，吴吟千载发清雄。","湖山照碧朦胧日，鞍马欺寒料峭风。","春入花梢人易感，莫教房闼叹飞蓬。"]},{"t":"和张咏老知县","f":"七言律诗","c":["照蔀辉辉碧夜光，贫儿那复苦悲凉。","得鱼始信筌无用，斲垩终期鼻不伤。","我类槁苗犹欠雨，君同脩竹饱经霜。","诗成病眼昏加涩，欲写还忧细作行。"]},{"t":"和张彦智中秋对月","f":"七言律诗","c":["万里青天霁色开，嫦娥驾玉上云来。","楼中胜饮八仙聚，物外清谈三语该。","空翠水光争滉漾，漏声钟韵共徘徊。","秋盘应爱金樱好，红抺佳人醉里腮。"]},{"t":"和张彦智对雪","f":"七言律诗","c":["雪山何处觅瞿昙，压尽江南瘴与岚。","待伴可堪风作党，交光应喜月成三。","濯巾漉酒供杯勺，涉笔联诗尚笑谈。","柳絮自今轻谢句，使君才气擅东南。"]},{"t":"和李难老","f":"七言律诗","c":["半生场屋弄朱衣，犹喜春来破白归。","同辈交游惟我拙，一时人物似君稀。","风神要在山庭峻，辞吐初疑锯屑飞。","州县未应淹骥足，钓名谁羡子陵矶。"]},{"t":"和沈次韩秋日雨后督子厚报","f":"五言律诗","c":["江槛连朝雨，山斋昨夜凉。","不知新稻熟，深怪晚炊香。","得句君应喜，闻风我漫狂。","绣溪行乐处，云水几千章。"]},{"t":"和沈进可检法秋夜饮客待月","f":"五言律诗","c":["欲雨云容合，濒江水气浮。","笑谈初入夜，灯火适逢秋。","巧借三豪便，还成一醉谋。","投琼酬木李，秪使老夫羞。"]},{"t":"和连圣举呈张彦智","f":"七言律诗","c":["公望岩岩映广东，曲江重见旧家风。","威行草木霜争肃，春到湖山雪自融。","至喜此心鱼鸟共，去思前日吏民同。","从今不复忧兵火，却敌如公笑语中。"]},{"t":"和邹进士","f":"七言律诗","c":["望外青山便到家，冯驩何患出无车。","坐逢石鼎应联句，箧有龙潭敢斗茶。","樽酒几时同竹叶，功名终日鉴菱花。","君看一雨苏群槁，所至人心乐否耶。"]},{"t":"和陈勉仲二首 其二","f":"七言律诗","c":["相逢怜我太衰颜，冰雪精神照座间。","霁日有情茶乳合，春风无力柳丝閒。","肯从逋客来三径，秪恐佳人赋二山。","旧说毛公今见否，似闻新向玉京还。"]},{"t":"和陈勉仲二首 其一","f":"七言律诗","c":["人似平原字亦颜，诗成长在笑谈间。","试看落笔云烟疾，难放摇春草木閒。","美俗未容窥制锦，劝耕聊得伴行山。","惭将郑腊酬荆璞，无怪年时债未还。"]},{"t":"和陈勉仲春日偶成二首 其二","f":"七言律诗","c":["江表归来得自由，旧乡能复到温柔。","辞源已见流三峡，笔力当期挽万牛。","白日忍从黄雾塞，青天那复黑云浮。","扫除骄寇还强汉，会有忠良告远猷。"]},{"t":"和陈勉仲春日偶成二首 其一","f":"七言律诗","c":["帷幄何人正坐筹，匈奴轻汉索怀柔。","回銮未睹迎天驷，劝穑还惊出土牛。","雨过池塘新涨绿，春归原野霁烟浮。","中兴自古须群策，更愿君王慎厥猷。"]},{"t":"和周少隐实录院对竹三首 其三","f":"七言律诗","c":["窗寒疏竹共萧骚，可笑圆荷着露凋。","实录成书辉日月，奉常新乐奏咸韶。","佳篇千里来青琐，好梦连宵到绮寮。","湖海固应聊尔耳，伫看丹诏下公朝。"]},{"t":"和周少隐实录院对竹三首 其二","f":"七言律诗","c":["老来须鬓白刁骚，犹喜丹心未遽凋。","秋赋肯甘同宋玉，昼眠聊复继边韶。","翩翩幽鸟随风屐，炯炯寒灯伴夜寮。","多谢故人珠玉寄，水云堆里望天朝。"]},{"t":"和周少隐实录院对竹三首 其一","f":"七言律诗","c":["夫子文章仆命骚，高标宁若岁寒凋。","惯看雄辩朝挥麈，想见清吟夜度韶。","老去荷君频折简，时来容我尚同寮。","区区长倩何为者，不乐平原意本朝。"]},{"t":"和彦时兄腊雪六首 其六","f":"七言律诗","c":["举首西风漫障尘，清无纤翳六花新。","谢庭拟似吟飞絮，洛浦飘飖见丽人。","漏箭不知楼外晓，觥筹先发坐中春。","兔园盛集应难继，空想当时主与宾。"]},{"t":"和彦时兄腊雪六首 其五","f":"七言律诗","c":["厌闻饥雀噪空囷，犹喜茅斋未遽倾。","屑玉岂劳青女送，飞花聊混白云霙。","预占岁稔矜祥旧，不择贫家荷施平。","早晚林梢挂寒日，为回和气慰饥茕。"]},{"t":"和彦时兄腊雪六首 其四","f":"七言律诗","c":["瑶林交映出风尘，便觉寒门气象新。","莫讶窗前群噪鹊，须怜江上有归人。","抛砖已喜来荆璞，斲垩无劳运郢斤。","坐拥红金饶大嚼，一时高会幕中宾。"]},{"t":"和彦时兄腊雪六首 其三","f":"七言律诗","c":["敢以箪瓢傲廪囷，撇醅聊复笑还倾。","为言空腹朝搜句，不觉寒窗夜集霙。","泽浃寰区成地富，光生蓬荜见天平。","预占有岁从今始，廊庙何忧不及茕。"]},{"t":"和彦时兄腊雪六首 其二","f":"七言律诗","c":["一洗乾坤不动尘，瑶台银阙斗清新。","齐腰欲究安心法，乘兴当为访戴人。","晔晔寒江归钓艇，丁丁虚谷动樵斤。","二诗远比幽兰胜，击节悬知众所宾。"]},{"t":"和彦时兄腊雪六首 其一","f":"七言律诗","c":["不耕何敢叹无囷，多谢先生早见倾。","望岁比同伤再潦，逢年今共快三霙。","光凝夜旦千山晓，势合高卑万壑平。","坐想袁安门未扫，洛阳谁复念孤茕。"]},{"t":"和彦时兄赠王广济","f":"五言律诗","c":["往矣古循吏，贤哉今长民。","牛羊归落日，桑柘殿馀春。","共学知名久，相逢见面新。","疮痍赖休养，犹喜见斯人。"]},{"t":"和彦逢弟春日即事","f":"七言律诗","c":["杨花如雪菜花黄，路出初郊正日长。","喜对新诗醒病眼，会逢膏雨沃骄阳。","过僧竹院茶争美，酌客山堂酒倍香。","常恨抗尘仍走俗，不知身在水云乡。"]},{"t":"和荀晋仲题法隆韵","f":"五言律诗","c":["去来何所喜，一雨应澄清。","憔悴有生理，叹嗟成颂声。","酒垆从客醉，村疃问农耕。","深得诹询意，谁能继此行。"]},{"t":"和赵养正春日游魏园","f":"七言律诗","c":["藜杖芒鞋信脚行，宿云披絮雨初晴。","溪边草色青毡合，竹外山光翠盖横。","弱柳弄閒无限思，小桃含笑不胜情。","清明此去旬馀日，花底能寻载酒盟。"]},{"t":"和赵积中","f":"七言律诗","c":["入室芝兰气不殊，逢君还忆见君初。","梅花正喜春悬凤，藿叶俄同夏鲙鱼。","下榻旧闻看孺子，负荆谁复谢相如。","艰难正诎平戎策，及早东游叩帝居。"]},{"t":"和闾必志见寄韵","f":"七言律诗","c":["老矣诗才欠壮观，羡君閒燕富清欢。","染羹早厌誇鼋指，食肉应宜谢马肝。","送客篇章堪寄远，论文杯勺自驱寒。","扁舟近过池头否，百丈西南水欲乾。"]},{"t":"和秦寿之中秋玩月三首 其三","f":"七言律诗","c":["肠断江城敛暮烟，一声清笛短亭前。","扬舲共喜风初转，戏綵当期月正圆。","水落双溪和石出，霜馀叠嶂与云连。","令人暗想昭亭路，屈指归来又四年。"]},{"t":"和秦寿之中秋玩月三首 其二","f":"七言律诗","c":["湖光无际接云烟，举酒登临夕照前。","坐送落霞还杳霭，倚看明月上高圆。","清谈浩渺河源注，丽句纵横绣段连。","归去凤池知不日，山城岑寂记今年。"]},{"t":"和秦寿之中秋玩月三首 其一","f":"七言律诗","c":["一樽芳酒起沉烟，绝胜红裙拥后前。","山色水光相上下，月华秋气共清圆。","佳时令我思韩愈，好梦逢君想惠连。","老大不知追逐乐，却因妍唱惜流年。"]},{"t":"和秦寿之题天祚宫","f":"七言律诗","c":["洞天无际复无旁，乔木梢云十万章。","身外轩裳谁系绾，壶中日月自舒长。","平生尘垢烦三沐，投老功名笑五浆。","白鹿青牛今在否，一声秋磬上寥阳。"]},{"t":"和秦寿之题黄州郡楼","f":"五言律诗","c":["西北张霞绮，东南漾月波。","登临筇作马，吟咏笔翻河。","思与苍霞远，情同白水多。","新诗清且丽，标致压阴何。"]},{"t":"和秦寿之题靖安栖霞观","f":"五言律诗","c":["飞观临无地，江天在目中。","晚霞工射日，秋水欲浮空。","蓼岸深迷绿，枫林远映红。","归欤还可喜，千里一帆风。"]},{"t":"和秦寿之题蕲春驿浸月轩","f":"五言律诗","c":["千山初过雨，万籁不鸣风。","宝鉴沉寒水，冰轮上太空。","竹梢低蘸碧，枫叶冷浮红。","终欲金沙去，经营一亩宫。"]},{"t":"和袁望回","f":"七言律诗","c":["千古风流忆孔明，老龙高卧志存身。","强陪簪绂更三圣，安坐江湖又四春。","便合痴狂称达者，谁能穷悴作骚人。","一杯聊复从公醉，要见予言总是真。"]},{"t":"和陶尉喜雨呈张文伯","f":"七言律诗","c":["贺客休辞酒盏深，使君心是老农心。","精诚已致当时雨，膏泽将为异岁霖。","得水槁苗俱竞秀，乘秋高鸟自能吟。","宣风宜有中和作，戛玉锵金播八音。"]},{"t":"和高守无隐官闲即事 其二","f":"七言律诗","c":["谁怜村落笑歌稀，全把茶瓯当酒卮。","枯槁又经三月雨，穷愁聊付一篇诗。","窗间远岫青千叠，楼外长天碧四垂。","何日获陪文字饮，欲翻妍唱入新词。"]},{"t":"和梁宏父二首 其二","f":"七言律诗","c":["功名须向壮年收，顾我摧颓已白头。","节晚独存松柏劲，岁寒还见雪霜浮。","老将耄及从人笑，醉欲眠时遣客休。","眼力尚能观细字，诗筒经卷且优游。"]},{"t":"和梁宏父二首 其一","f":"七言律诗","c":["时来谈笑取侯封，清旷宁容雅志从。","上圣急贤齐舜禹，群公引类迈夔龙。","非材似我十围栎，有用如君千丈松。","邂逅相逢辱倾盖，能令瓦釜配黄钟。"]},{"t":"和萧山临川亭壁间留题韵","f":"七言律诗","c":["水外峰峦碧四环，雨多门径藓苔斑。","滞留又及炊新粟，欢喜何当见旧山。","招隐有诗来霅上，倦游无梦到云间。","西兴十里秋潮晚，坐数扁舟带月还。"]},{"t":"和曾式古","f":"七言律诗","c":["白云飞处见层巅，回首风樯去若仙。","旧隐已锄三径菊，新吟聊愬一囊钱。","春归沂水还相乐，秋到盱江盛有年。","更着綵衣歌且舞，高堂侍沥奉周旋。"]},{"t":"和程德远二首 其二","f":"五言律诗","c":["未尽通宵话，犹如一日秋。","壮怀天共远，归意雨同留。","灯烬何明灭，蛩声静应酬。","十年为客梦，应不负瀛洲。"]},{"t":"和程德远二首 其一","f":"五言律诗","c":["寓问发函旧，论交倾盖新。","几年瞻翰墨，今日侍光尘。","禦侮烦骁将，扶颠倚大臣。","相逢更可恨，对酒漉陶巾。"]},{"t":"和董令升舍人","f":"七言律诗","c":["雨馀沙路润无泥，潋滟溪流与岸齐。","苒苒年华催我老，酣酣春意得人迷。","联珠便觉新诗富，浮玉还听雅唱低。","杨柳缓摇阴正午，谁家篱落一声鸡。"]},{"t":"和董令升舍人梦中得句","f":"七言律诗","c":["早晚天书下紫泥，如今人物擅三齐。","才华好自銮坡进，诗思休从蝶梦迷。","深院日迟黄鸟啭，长桥风软绿杨低。","春容不用相撩拨，老去心情似木鸡。"]},{"t":"和鲁如晦春日过定远山口","f":"五言律诗","c":["雨足塍塍水，春晴处处花。","畏涂双只堠，荒戍两三家。","心折朝鸣鹿，魂惊暮集鸦。","想君行役苦，愁蹙不成嗟。"]},{"t":"和窦又勇秋日见访阻雨见赠","f":"七言律诗","c":["风雨萧萧暮不休，顿添寒色送穷秋。","已荒深院菊犹在，欲去短亭人强留。","千里书迟空噪鹊，四邻砧乱混鸣鸠。","相逢棋战宜终日，卧稻从他烂不收。"]},{"t":"和詹德秀出南汰二首 其二","f":"五言律诗","c":["小沼鸣蛙吹，虚堂堕燕泥。","对花容命酒，书事喜分题。","僧舍乔林北，田家古道西。","鹁鸠晴唤妇，谷谷傍人啼。"]},{"t":"和詹德秀出南汰二首 其一","f":"五言律诗","c":["晓出东郊路，春霖数尺泥。","湖山供胜赏，花草觅新题。","坐听鸣鸿北，归看落日西。","乍晴何所喜，芳树早莺啼。"]},{"t":"和韵寄董令升舍人","f":"七言律诗","c":["曾将燕石报琼华，别后哦诗愧莫涯。","空腹但看长柄械，缓行何用短辕车。","神驰邓步弥天葑，梦入朋溪夹径花。","何日天台寻药去，女仙迎笑饭胡麻。"]},{"t":"和潘泽之沈元吉泛舟湖上","f":"五言律诗","c":["散骑真前辈，休文即当家。","泛舟成丽句，散绮见馀霞。","惊去沙鸥没，招来酒旆斜。","春归何处觅，篱角见金沙。"]},{"t":"和褒山因老二首 其二","f":"七言律诗","c":["岛可文章似出家，不将言语落浮誇。","雪中令我思风絮，天上因君合雨花。","一炷飞烟云天矫，数行佳树玉槎牙。","山高殊觉青霄近，扪虱南窗向日华。"]},{"t":"和褒山因老二首 其一","f":"七言律诗","c":["湖上逢师又到家，别来诗句好相誇。","休嗟晚菊今迷草，且喜寒梅欲放花。","丈室香温岩宝坐，将坛风软拥高牙。","相思对雪酬珠玉，不觉茅檐送月华。"]},{"t":"和戴禹功水云馆留题","f":"七言律诗","c":["兵火间关我尔同，相逢聊喜话匆匆。","山长不碍飞云去，江涨应从远水通。","白鹭晚潮初浸脚，雨花遗址正横空。","临风遐想成惆怅，千古兴亡一局终。"]},{"t":"和魏定父","f":"五言律诗","c":["十里南溪路，思君一望间。","黄花秋色老，红叶露痕殷。","似说亲朋集，遥知杖屦閒。","徘徊松径晚，踏破紫苔斑。"]},{"t":"咏梅示魏吉老","f":"七言律诗","c":["孤芳常恐百花知，桃李纷纷亦强追。","照雪精神应自喜，逼人风味不吾亏。","幽香隐约留衣袂，疏影玲珑鉴砚池。","欲识东君好消息，夜来青鸟宿南枝。"]},{"t":"咏雪","f":"七言律诗","c":["白榆风起匝天来，透隙穿帘醉眼开。","毡衬庭阶茸妥贴，带盘山径玉萦回。","根行万国将宜麦，香动千林独放梅。","閒把银杯评柳絮，始知谢女亦非才。"]},{"t":"夜听刘昭远弹琴","f":"七言律诗","c":["河阴高转月光流，露脚斜飞夜气收。","焦尾冷含三尺水，悲风弹破一庭秋。","广陵别后多新操，子敬亡来绝旧游。","欲洗世间筝笛耳，为言干斛不须求。"]},{"t":"夜泊官牌夹口大风追和陈去非岁晚感怀","f":"七言律诗","c":["咿喔邻鸡夜向阑，晓风骄挟晓霜寒。","吹灯强取残书读，拨火重寻远信看。","绿蚁已应浮腊瓮，青丝行复送春盘。","旅怀欲倩高鸿寄，凭仗新诗付笔端。"]},{"t":"房陵秋日","f":"七言律诗","c":["新诗来处自房州，已及瓜时叹滞留。","曾望碧云频送目，又惊红叶再敲秋。","千山不隔清风远，两地应同素月流。","游刃似君诚利器，只今无复见全牛。"]},{"t":"放船和子薳韵","f":"五言律诗","c":["冬温寒日好，岁晚早梅开。","帆脚随风转，江流与岸回。","坐怜青嶂远，静见白鸥来。","水驿三千里，斯游亦壮哉。"]},{"t":"苦寒","f":"七言律诗","c":["风屑琼寒透薄帷，拥裘端与火相宜。","煖回炽焰身成直，拨到残灰手欲龟。","赠炭尚谁怜正曜，授薪还自愧支离。","不甘力请从缁侣，苦调寒窗强作诗。"]},{"t":"雨中宿竹林寺谢尉仁父见访","f":"七言律诗","c":["幽人好客不嫌纡，带水拖泥辱顾予。","僧舍顿惊樽有酒，旅庖那患食无鱼。","敢辞数里来相遇，要使它时付特书。","新竹茂林中扫径，一瓯春雪少踌躇。"]},{"t":"饱食","f":"五言律诗","c":["予亦属厌耳，女宽何叹三。","一箪傥知足，八珍自忘贪。","驼峰擅西北，瑶柱誇东南。","但愿无是馁，藜羹非我惭。"]},{"t":"哀汤与立父 其三","f":"五言律诗","c":["尚记宣和末，贤科擢阿戎。","义方传辇下，士誉走江东。","贺厦心虽切，披云意自忡。","思君想眉目，悲咽对西风。"]},{"t":"哀汤与立父 其一","f":"五言律诗","c":["薄俗久不竞，丘园多逸民。","闻君轻去世，令我重沾巾。","一梦苕溪晓，千年石堵春。","人情不能已，南望哭江滨。"]},{"t":"哀汤与立父 其二","f":"五言律诗","c":["一门今七世，谁复似君家。","盛事追公艺，高风映伯华。","板舆方就养，玉树遽兴嗟。","叔子今何在，魂应到马牙。"]},{"t":"哀陈夫子 其一","f":"五言律诗","c":["不见陈夫子，依稀四载馀。","云亡前日信，报葬几时书。","玉轴千篇在，牙签万卷储。","九原应有恨，新第落成初。"]},{"t":"哀陈夫子 其二","f":"五言律诗","c":["去矣君何速，闻之我重悲。","席尘埋古鼎，书蠹入新诗。","鸿雁嗟安仰，枌揄痛莫追。","木瓜惭未报，临纸涕涟洏。"]},{"t":"哀周然明","f":"七言律诗","c":["三荐渠能老一儒，班超投笔好从吾。","功名到手身先死，诗礼传家道不孤。","千里新封从马鬣，百年馀庆萃鹓雏。","西风哀挽桐川上，傥有青刍致奠无。"]},{"t":"哀徐朝义恭人潘氏 其二","f":"五言律诗","c":["城见三千岁，人终八十春。","从夫安乐近，拜佛率陀新。","婉娈书彤管，凄凉叹棘薪。","中郎有贤子，遗泽擢平津。"]},{"t":"哀徐朝义恭人潘氏 其一","f":"五言律诗","c":["爱子心惟壹，宜家语不烦。","雨添南涧藻，风偃北堂萱。","郁郁今同穴，诜诜正满门。","善哉摩顶记，归奉大慈尊。"]},{"t":"宣城驿中送建康倅赵纯中","f":"七言律诗","c":["芍药飘零雨洗春，江城柳色静无尘。","扁舟未果寻归路，小驿那堪送故人。","万里云天心共远，一龛灯火话相亲。","因风无惜沾馀馥，我亦贫儿望富邻。"]},{"t":"春日书怀 其一","f":"七言律诗","c":["野桃经雨烂争华，似促畦丁种早瓜。","不见少年閒信马，空怜寒士出无车。","泥融近水芹抽叶，地暖依墙荠放花。","偶忆惠连春草句，夜来魂梦到天涯。"]},{"t":"春日书怀 其二","f":"七言律诗","c":["高文知已动天庭，昨日春雷下六丁。","济旱会施惟肖雨，举贤先应少微星。","行趋北阙形神健，坐对东风醉梦醒。","连日暖烟随处好，吴山应胜越山青。"]},{"t":"春日无为道中","f":"五言律诗","c":["旱甚山光暗，风颠日色微。","桑芽虻翅小，荻笋彘肩肥。","野寺看题壁，村垆问典衣。","春容良不恶，杨柳正依依。"]},{"t":"春日有感示魏定父","f":"七言律诗","c":["聚散时来不自由，相逢相别欲何尤。","韦皋况有三年约，陶谷端非一日谋。","残角为谁惊晓梦，远山多事惹春愁。","故园又作骊驹赋，尚幸持觞为劝留。"]},{"t":"春日次韵张叔元","f":"七言律诗","c":["迟日轻风过雨天，草青南陌欲生烟。","江湖节物登王鲔，村落归心起杜鹃。","已办寻芳游野寺，何当修禊泛溪船。","路逢少妇携笼去，为说蚕儿向雨眠。"]},{"t":"春日郊行和郭希鲁二首 其二","f":"七言律诗","c":["坐对烟江叠嶂图，何如门外翠屏纡。","寻芳敢擅携筇去，命友应从折简呼。","酒里光阴閒活计，诗馀情思静功夫。","浪吟痛饮真难遇，休问西山日欲晡。"]},{"t":"春日郊行和郭希鲁二首 其一","f":"七言律诗","c":["萦风杨柳绿丝长，过雨桑麻沃以光。","联骑不妨多载酒，看花无用更烧香。","望穷岩电搜诗眼，愁转车轮感别肠。","胜集清游定何处，它年曲水记流觞。"]},{"t":"春日偶成","f":"七言律诗","c":["馀生今赴迩英朝，似说夔龙许续貂。","枯蘖遂承新雨露，苍鹰应识旧云霄。","废兴须信关时命，劳逸谁能问贯条。","十载山林劳梦寐，五更天仗听箫韶。"]},{"t":"春日游西塔示本上人","f":"五言律诗","c":["暇日搜奇胜，羸骖适莽苍。","幽花撩醉眼，早麦慰饥肠。","佛屋几间在，村墟三里长。","廉纤晚来雨，未觉客心伤。"]},{"t":"春残次韵张叔元","f":"七言律诗","c":["乱红狼籍紫苔斑，帘捲东风雨脚残。","蜀酒渐宜消昼永，单衣犹觉怯朝寒。","玲珑有客双摇辔，矍铄何人一据鞍。","芍药酴醾晴更好，劝君休作梦中看。"]},{"t":"春雪","f":"七言律诗","c":["一夜春寒梦寐清，柳梢梅萼颇关情。","山川千里玉为路，楼观半天云满城。","径醉已从酾酒去，稍晴当办出郊行。","东君底事偏芳草，刬尽依然上砌生。"]},{"t":"独步","f":"五言律诗","c":["饱馀惟欲睡，散睡步东园。","雨足富莲子，年丰多稻孙。","崎岖穷竹径，诘曲遍花源。","何必冠童辈，偕来笑语喧。"]},{"t":"秋日书怀 其一","f":"七言律诗","c":["断虹收尽晚风凉，扑鼻谁家社酒香。","门外山横青玉案，屋头榴绽紫罗囊。","对吟已觉输新俊，遇酒还能发老狂。","坐想西园梨枣熟，昔年犹记拉君尝。"]},{"t":"秋日书怀 其二","f":"七言律诗","c":["一别成均十九秋，断肠千里致书邮。","可怜率土民心固，端为当年圣泽流。","此去会看还北狩，夜来先梦到东州。","尊君正是吾侪事，可但南冠学楚囚。"]},{"t":"秋日书怀 其三","f":"七言律诗","c":["到齐何日醉青州，久矣平原困督邮。","避地未容行信步，汎江聊得卧安流。","望穷落鹜千山晚，梦断惊飙万壑秋。","安得尚方三尺剑，扫除骄寇献俘囚。"]},{"t":"秋日即事三首 其三","f":"五言律诗","c":["俛仰黄花集，澄清九月秋。","预愁新任迫，难为故人留。","风去山光合，江回水气浮。","何当脱羁绊，同办五湖舟。"]},{"t":"秋日即事三首 其二","f":"五言律诗","c":["今日知何日，西风正得秋。","天心方祚汉，人物合师留。","才略烦威敌，声名赖镇浮。","不妨临赋乐，汎汎有杨舟。"]},{"t":"秋日即事三首 其一","f":"五言律诗","c":["晚来何所喜，急雨洗新秋。","幸遂登高赋，应容遇胜留。","藕花明远近，鸥鸟任沉浮。","不用挥纨扇，何妨醉玉舟。"]},{"t":"秋日郊行","f":"五言律诗","c":["断桥临野水，疏屋见人家。","嫩绿几畦菜，深黄三径花。","断云行自逐，征雁望还赊。","好访韩湘去，山林养白鸦。"]},{"t":"秋日喜雨题周材老壁","f":"五言律诗","c":["大旱弥千里，群心迫望霓。","檐声闻夜溜，山气见朝隮。","处暑馀三日，高原满一犁。","我来何所喜，焦槁免无泥。"]},{"t":"秋日游南汰二首 其二","f":"五言律诗","c":["松篁团野色，葭薍接江氛。","芳菊开新雨，晴天扫片云。","村醪过寺共，风袂转山分。","邂逅梅夫子，清谈得致勤。"]},{"t":"秋日游南汰二首 其一","f":"五言律诗","c":["小雨沾秋旱，清曦霁晓氛。","山留归壑水，风送过江云。","碧瓦觚棱出，黄茅兔径分。","高僧似相喜，茗饮话殷勤。"]},{"t":"秋兴八首追和杜老 其三","f":"七言律诗","c":["云影曚昽日洒晖，金湖西畔晚阴微。","渔舟缭绕青山去，枫叶追随白鸟飞。","摩诘家风非世有，渊明心性与时违。","近来病瘠连诗瘦，翻爱西台字样肥。"]},{"t":"秋兴八首追和杜老 其八","f":"七言律诗","c":["迢迢山势去委蛇，林木东头见荻陂。","疏竹依岩秋迸笋，病桑经火雨生枝。","草侵药种多难辨，土拨松苗欲自移。","照眼谁家几枝橘，出篱丹实正离离。"]},{"t":"秋兴八首追和杜老 其一","f":"七言律诗","c":["湖外干戈半绿林，湖边葭薍晚森森。","风霾未放远山出，岚气又连凄日阴。","世乱且同吟啸乐，时来终快扫除心。","天寒况是开炉近，应有佳人赋藁砧。"]},{"t":"秋兴八首追和杜老 其五","f":"七言律诗","c":["翠壁苍崖水外山，山头茅舍两三间。","夜窗明月来临卷，昼户清风为启关。","霞绮障秋惊老眼，酒红潮面发衰颜。","集英一梦如今觉，犹忆当时晓趁班。"]},{"t":"秋兴八首追和杜老 其二","f":"七言律诗","c":["巉岩石壁半攲斜，茅栗丛中菊渐华。","风里断鸿书带草，山头飞叶汉浮槎。","柂楼索莫吟秋笛，戍火青荧咽暮笳。","争似渔翁最萧散，晚来和月卧芦花。"]},{"t":"秋兴八首追和杜老 其七","f":"七言律诗","c":["勋业休烦付考功，此生终待老山中。","宦情薄似贤人酒，诗思清于少女风。","秋雨养肥桑耳白，溪流濯出柳须红。","不堪世路频硗确，四十萧然秃鬓翁。"]},{"t":"秋兴八首追和杜老 其六","f":"七言律诗","c":["远水西来抱鹿头，山前草木带霜秋。","黄花雅意撩诗兴，红叶端能寄别愁。","日月奔驰双转毂，江湖漂荡一轻鸥。","干戈未戢中兴沸，蹴被空怀祖豫州。"]},{"t":"秋兴八首追和杜老 其四","f":"七言律诗","c":["辘轳世态一枰棋，销得秋来宋玉悲。","舒啸可无元亮意，哦诗如见少陵时。","江湖于我还萧散，田舍从他笑重迟。","异域故人今在否，青灯牢落夜相思。"]},{"t":"秋夜对月","f":"五言律诗","c":["青廓经新雨，扶疏桂影秋。","夜凉山色静，风细水光浮。","坐久因忘寐，诗成得散愁。","愿言乘此兴，同赋庾公楼。"]},{"t":"追和东坡张昌言喜雨呈同官","f":"七言律诗","c":["旱魃正须三尺雨，飞廉旋布四天云。","诗成采笔挥琼玖，酒到酡颜散缬纹。","莲沼滟翻宵溜急，槐庭清送午风薰。","欣欣千里农夫庆，衰病空惭老使君。"]},{"t":"追和东坡严车二雪诗 其二","f":"七言律诗","c":["雪满江城酒不赊，闭门那患出无车。","未容踏冻寻梅萼，应喜临风见柳花。","炭重乌银争晓市，蔬挑翠羽荷邻家。","何人正下红莲幕，大嚼蒸羊手更叉。"]},{"t":"追和东坡严车二雪诗 其一","f":"七言律诗","c":["公诗有意拂廉纤，令似欧阳韵更严。","犬子亦应惭赋缟，痴儿端合愧誇盐。","飞绵勃窣争平堑，冻笋槎牙欲堕檐。","胡避只今何处是，玉屏森映一峰尖。"]},{"t":"追和东坡送春和陈德夫","f":"七言律诗","c":["柳外风樯迅莫追，柳间迟日弄晴晖。","青春已作堂堂去，乌辔何由缓缓飞。","入户呢喃轻语燕，隔林咿轧静鸣机。","谁言四月芳菲尽，萱草葵花觉昨非。"]},{"t":"追和东坡倦夜一首","f":"五言律诗","c":["风阁开还闭，龛灯暗复明。","竹间听露滴，庭际看云行。","皎月千门静，微风一座清。","只今廷诤者，谁复继元成。"]},{"t":"追和老杜江上","f":"五言律诗","c":["独坐日将夕，凄凄风雨秋。","寒灯照孤屋，攲榻拥疏裘。","身世槐安国，功名蜃化楼。","归欤老居士，踪迹继浮休。"]},{"t":"追和李义山赋菊二首 其二","f":"五言律诗","c":["团团青盖小，拂拂御袍黄。","翠叶凌霜秀，繁英浥露香。","浮觞追北牖，饮水记南阳。","采采东篱下，行歌对草堂。"]},{"t":"追和李义山赋菊二首 其一","f":"五言律诗","c":["嫩萼犹封绿，繁英已醉黄。","雨馀三径晚，秋到一枝香。","滴滴盈朝露，晖晖映夕阳。","何妨浮玉斝，共醉木兰堂。"]},{"t":"送无为守郑深道移严州","f":"七言律诗","c":["世称儒雅擅青徐，今见君侯信不虚。","报政未容更绣水，除书先已易桐庐。","郡邻帝所旋趋召，地切家山勿恋居。","千乘来迎催去急，邦人何计挽行车。"]},{"t":"送刘元发归鄱阳次其韵","f":"七言律诗","c":["杖藜千里访茅茨，来赴当年一笑期。","白发我徒悲老大，青山君尚记艰危。","夜听高论因忘寐，昼味新诗可疗饥。","冬日迎长殊可爱，何妨去国少迟迟。"]},{"t":"送安丰判官江叔夜用菊花韵","f":"五言律诗","c":["冬温行色好，江上菊花黄。","乡味莼羹美，皇恩诰墨香。","招延从北海，吟咏继东阳。","别后如相忆，时应问草堂。"]},{"t":"送江致远归建昌","f":"七言律诗","c":["翩然归兴不吾留，应为高堂念远游。","数日语离良作恶，几时书到得无愁。","白沙翠竹千山晚，朱实黄花万里秋。","后夜西风茅店月，醉吟应不费冥搜。"]},{"t":"送许判官志仁","f":"七言律诗","c":["是行犹及豫章春，闻说逢迎有故人。","倾盖为君殊快意，掺袪令我重伤神。","向阳花木初开叶，得雨蛟龙已转身。","江上新晴应更好，绿杨如幄草如茵。"]},{"t":"送陈南仲守象州","f":"七言律诗","c":["熊轼朱轓照野明，知君今赴象山行。","荣观共作叹嗟语，静念独伤离别情。","畏景逼人才数日，脩涂计此始三程。","至时应在中元后，好寄双鱼慰友生。"]},{"t":"送彦逢弟赴西兴盐场","f":"五言律诗","c":["闻道西兴去，全家共小舟。","别离江北岸，怀抱海东头。","闪闪风帆远，滔滔雪浪浮。","苕溪在何许，应为故人留。"]},{"t":"送徐次公罢历阳任归三衢","f":"七言律诗","c":["闻说家书赋鹡鸰，归欤难弟见难兄。","接联本作二年调，解印俄成千里行。","故国一犁春雨足，长江三板暮潮平。","烂柯况是神仙宅，招隐诗成好寄声。"]},{"t":"送徐季公运干罢任","f":"七言律诗","c":["羁栖无柰老而穷，又见徐卿马首东。","快意一时荷叶雨，增明千里稻花风。","高材合在云霄上，胜处能忘涧壑中。","法护相从如问我，为言踪迹与君同。"]},{"t":"送浮屠昙远归无为持钵","f":"七言律诗","c":["一筇春色满郊畿，弹指淮南迅若飞。","丈室正须香积供，孤云聊作故山归。","长安城里风烟好，锦绣溪头笋蕨肥。","我有上林桃李约，未容随子赴亲闱。"]},{"t":"送浮屠善慧东游","f":"五言律诗","c":["西去方祈谷，东来适佩萸。","凄风梧脱叶，积雨稻生蚨。","诗骨寒岩木，禅心古庙炉。","莫将明月句，容易谒姑苏。"]},{"t":"送浮屠道郭云游","f":"五言律诗","c":["何必袁州去，尘尘小释迦。","一筇非外物，四海即吾家。","晓色霜还重，秋容菊正华。","此行良不恶，冬笋已排牙。"]},{"t":"送秦德久守安丰","f":"七言律诗","c":["历水分携十六年，相逢须鬓尽苍然。","喜君宦况新来好，许我交情老更坚。","小雨送行春溜急，长杨留别午阴圆。","画船插帜澄江远，回首风帆指绣川。"]},{"t":"送钱逊叔出守袭庆赐出身除职","f":"七言律诗","c":["赐对金銮下九天，旋闻熊轼为驱前。","人从芸阁初分直，桂折蟾宫乍得仙。","刺史江山聊复尔，翰林风月自依然。","下车快草东封疏，今去祥符正百年。"]},{"t":"送淮西转运判官李彦恢还朝","f":"七言律诗","c":["江头旗影弄青红，似说朝天四牡东。","抱病不容攀辔勒，送行那复遣儿童。","田均税敛千年利，福及疮痍九郡同。","此去定知还禁近，从来阴德报宜丰。"]},{"t":"送董令升舍人归朋溪二首 其二","f":"七言律诗","c":["仙舟东去访金华，歌彻骊驹向水涯。","试问玉堂司凤诏，何如蓬岛驾云车。","雨馀翠筱初翻箨，风暖丹葵欲放花。","天气清和行色好，江南江北半桑麻。"]},{"t":"送董令升舍人归朋溪二首 其一","f":"七言律诗","c":["西掖归来鬓未华，著书论字当生涯。","撑肠何止五千卷，溢箧定踰三十车。","秋露青黄新种橘，春风红紫旧栽花。","东还贪逐朋溪乐，只恐金銮诏草麻。"]},{"t":"送端溪尉张达城挈家南归","f":"七言律诗","c":["年时萧寺雪初晴，闻道君来眼倍明。","送别又看秋欲去，论交还感盖初倾。","帆张须水秋潮涨，路入铅山晚翠横。","快向端溪从吏隐，归来稳步上蓬瀛。"]},{"t":"溯流入栅江","f":"七言律诗","c":["久客心肠怯溯洄，不堪官事紧相催。","踏霜人去繵风吼，冲浪舟行岸冻开。","雪尽野梅红剪腊，春回溪水绿生苔。","穷愁好逐残年尽，三日元正与泰来。"]},{"t":"哭韩积中二首 其二","f":"五言律诗","c":["多能倾相府，高义著房州。","脱略通侯贵，追随逐客游。","敢论当世比，曾向古人求。","怊怅今楼护，黄泉已再秋。"]},{"t":"哭韩积中二首 其一","f":"五言律诗","c":["命矣穷张籍，归哉病长卿。","焦湖家自远，畏日我同行。","想像分携处，依稀謦欬声。","仙踪向西路，回首泪纵横。"]},{"t":"夏日归自宝林二首 其二","f":"五言律诗","c":["远岫升初日，长林霭曙烟。","峰回遥见塔，溪转静鸣泉。","竹箨新披锦，茅花欲擘绵。","清和多美荫，归路得蹁跹。"]},{"t":"夏日归自宝林二首 其一","f":"五言律诗","c":["十里招提路，崎岖祝圣归。","青黄原上麦，红白草间薇。","正看云容合，俄惊雨脚飞。","馀花被沾湿，芳气袭人衣。"]},{"t":"夏月自六安舟行还安丰","f":"七言律诗","c":["滟滟溪流涨渌波，乍晴天气自清和。","露梢抽翠交新竹，风叶翻红飐嫩荷。","水外远山晨雾重，道傍佳树午阴多。","头旋更苦舟摇兀，说与篙师住得么。"]},{"t":"悯旱","f":"七言律诗","c":["食贫那识小槽红，回也箪瓢久屡空。","翘候载芟歌济济，忍看云汉叹爞爞。","困穷转觉蓬心隘，憔悴犹怜菜颊丰。","坐对骄阳思霈泽，日占鸣鹳望穹窿。"]},{"t":"烧火用陈西麓韵","f":"五言律诗","c":["烧火驱寒去，衔杯待暖回。","家书万金值，怀抱一时开。","腊雪犹栖树，风光已着梅。","相过随处好，未怪损梅苔。"]},{"t":"能赋台","f":"七言律诗","c":["万顷玻瓈水浸空，台前佳色咏难穷。","倚栏人在烟霞外，落笔诗成笑语中。","属句畏惭非孟子，供欢端合有车公。","解将能否分优劣，过眼昭然向与雄。"]},{"t":"读韦苏州诗因用陪王郎中寻孔徵君韵","f":"五言律诗","c":["我才伤朴樕，吾道属艰难。","未遂三豪遇，那知一笑欢。","湖山晨溢翠，风雨夜沾寒。","归棹秋无几，游吴意未阑。"]},{"t":"逍遥堂二首 其二","f":"五言律诗","c":["娜婀风前竹，空濛雨外山。","孤云心共远，短艇兴俱还。","酒有双莲胜，诗无一字閒。","因君成怅想，时到梦魂间。"]},{"t":"逍遥堂二首 其一","f":"五言律诗","c":["独坐虚堂寂，烟销瓦博山。","出游鱼自乐，飞倦鸟知还。","花气清风远，槐阴白昼閒。","逍遥入诗思，落笔笑谈间。"]},{"t":"宿吉祥寺赠应上人","f":"七言律诗","c":["窗前脩竹翠摩云，清閟题轩念昔人。","三纪重来惊隔世，一言相契定前因。","携尊得得纷亲友，抉藕累累萃里民。","祖意如来烦指似，迷舟何幸济通津。"]},{"t":"寄孙次卿","f":"七言律诗","c":["归来啜菽得无愁，但觉官身不自由。","敢倩双鱼传尺素，要知一日似三秋。","射阳别后从新辟，幽谷公馀获胜游。","尚忆龙盘分袂处，五更残月在山头。"]},{"t":"寄余元明","f":"七言律诗","c":["对月令人忆子年，别来重见望舒圆。","閒中情性南无界，物外光阴小有天。","连喜得官如得句，惯看乘马似乘船。","朝回共醉知何日，准拟春衣当酒钱。"]},{"t":"寄别江茂德赴麻城丞二首","f":"七言律诗","c":["此行何处有淹留，新得中郎万斛舟。","会见马群空冀野，还同鹤驾到扬州。","鲈鱼出网红翻锦，江水浮山绿泼油。","回首风樯惜轻别，一声鸿雁起沧洲。"]},{"t":"寄题峡州楚塞楼","f":"七言律诗","c":["江向西陵势渐平，万山环合翠峥嵘。","须知楚国尝为塞，不为涪翁浪得名。","人若此贤真俊杰，楼还旧观焕神明。","临风每听滩声咽，似怨张仪作暮横。"]},{"t":"梅隐亭","f":"七言律诗","c":["无虑无营得自如，乱红狼籍绿阴初。","莫贪视盗诛锄术，轻换齐民种莳书。","风物最怜清且好，宾朋那患数斯疏。","高谈亹亹还终晷，坐觉庭花影上裾。"]},{"t":"清明即事","f":"七言律诗","c":["柳径桃溪碧草芳，故园遥寄水云乡。","老来转使宦情薄，春思颇增诗兴长。","教子文书容自勉，逢人尊酒为谁忙。","海棠却似怜衰朽，依倚东风试晚妆。"]},{"t":"隐静道中","f":"七言律诗","c":["马头聊复问诸涂，东指宣城百里馀。","水外山屏供步障，道傍蛙吹接行车。","青归柳色浮烟里，红入花光过雨初。","春意似同人意好，此行那患食无鱼。"]},{"t":"雪晴三首 其三","f":"五言律诗","c":["气暾寒日晓，光照远山晴。","邹谷有春意，袁门闻履声。","映书何自苦，炙背不妨清。","邂逅逢诗将，高吟眼倍明。"]},{"t":"雪晴三首 其二","f":"五言律诗","c":["湖山开宿霭，院落快新晴。","滉漾溶银色，潺湲过雨声。","味增茶品胜，光夺月华清。","放出东墙角，梅花数点明。"]},{"t":"雪晴三首 其一","f":"五言律诗","c":["雪压千山净，云披万里晴。","木冰争霁色，檐雨碎寒声。","静映吟窗冷，轻浮茗椀清。","最宜今夜月，来借短檠明。"]},{"t":"鹿鸣宴","f":"七言律诗","c":["苍颜华发老书生，来赴公堂宴食苹。","曾预宣和闻喜集，重观乾道计偕行。","绣衣劝驾追前哲，熊轼宾贤继列城。","久矣邦人虚桂籍，正须公等振英声。"]},{"t":"喜雨","f":"七言律诗","c":["雷声翻海电光红，濯濯蔷薇一夜空。","云气共看渊跃蜧，雨祥曾验叶生虫。","伫期多稼干箱富，先庆来麰百室丰。","饰喜自惭樽酒薄，只将香火向穹窿。"]},{"t":"紫薇花","f":"七言律诗","c":["过尽红薇到紫薇，广庭高槛见芳菲。","缤纷不逐槐花落，拂掠应从燕子飞。","枝压画檐朝露重，影摇苔砌午风微。","何当草诏丝纶阁，伴我黄昏坐禁闱。"]},{"t":"腊梅和次韩韵 其一","f":"七言律诗","c":["一枝横亚竹梢黄，宫样新翻半额妆。","閒淡似宜冬后日，清癯应怯夜来霜。","生憎丹脸娇含酒，巧妒冰肌冷透香。","取蜡为花缘底事，浪吟空发少年狂。"]},{"t":"腊梅和次韩韵 其二","f":"七言律诗","c":["可怜风骨肖梅英，试问东君曷似生。","正色不从朱粉涴，耐寒犹怪雪霜轻。","论交薝卜君为胜，投社酴醾我更清。","纵美讵能齐众口，漫言异日许调羹。"]},{"t":"蒙城早行","f":"五言律诗","c":["残月千家闭，荒城万窍号。","举头华盖近，回睇启明高。","野迥霜迎面，风清冷透袍。","十年河上路，从此步金鳌。"]},{"t":"遣兴","f":"五言律诗","c":["步屧随儿辈，临池得凭栏。","久阴东虹断，小满北风寒。","点水荷三叠，依墙竹数竿。","乍晴何所喜，云际远山攒。"]},{"t":"酬吕公季","f":"七言律诗","c":["相逢宾戏快逢场，何幸轻投得夜光。","半面向怀精舍旧，一行今整汉阳装。","如君俊逸犹沉滞，顾我迂疏合退藏。","别乘未来霜候冷，客灯明灭漏声长。"]},{"t":"酬张进彦见寄","f":"七言律诗","c":["皇华应记去年曾，六辔驰驱问固陵。","道路向来荒枳棘，堤封从昔错沟塍。","烟销列嶂秋光远，木落长淮霁色澄。","自笑壮心穷未已，欲言言大怕人憎。"]},{"t":"酬李才叔见赠","f":"七言律诗","c":["篙师且缓莫予催，老眼逢君喜暂开。","相与未成招隐什，分携宜尽送行杯。","谁令急景堂堂去，我为佳人得得来。","万壑千岩终欲遍，归欤清梦转幽哉。"]},{"t":"酬陈勉仲勉仲寄示诸公所和黄字韵诗轴且责其归重念匹夫怀璧之罪不敢靳因复和其韵反之","f":"五言律诗","c":["失梳蓬鬓结，欠洗垢衣黄。","我欲齐荣辱，谁能较短长。","贱贫犹不去，富贵慎无忘。","岂敢贪怀璧，春秋戒越乡。"]},{"t":"酬周少隐赠行之什","f":"七言律诗","c":["我老无知独梦鱼，清风一枕午钟馀。","忽惊珠玉情相厚，便觉山林计不疏。","酒熟会看延客醉，诗成还复遣儿书。","何人竟得閒中趣，只恐无聊叹索居。"]},{"t":"酬章序臣二首 其二","f":"七言律诗","c":["老懒观梅喜见花，一枝聊复寄君家。","清香扑袂传春信，疏影摇窗借日华。","小小池塘从掩映，依依杨柳漫交加。","和羹风味今犹古，回首青青遂有涯。"]},{"t":"酬章序臣二首 其一","f":"七言律诗","c":["风梢摇落雪飞花，谁传江梅到我家。","曾把数枝分暗馥，要催群卉助光华。","高吟两绝那容继，胜赏双清蔑以加。","春不世情应委曲，十年留滞在天涯。"]},{"t":"酬蕲春王宰公明","f":"七言律诗","c":["致身华贯属华年，顾我驽痾久不前。","醉被长官轻骂郑，懒从学子竞嘲边。","功名有日还三杰，诗酒何人继八仙。","才业似君真独步，文章政事尽堪传。"]},{"t":"横枝山北别懿上人","f":"七言律诗","c":["青山终是慰人心，到处相逢不用寻。","顾我未能忘楚些，因君聊复效吴吟。","遥林入眼增双碧，羸马奔家竞寸阴。","何事横枝送南北，他年同此记分襟。"]},{"t":"题无为秀溪亭","f":"七言律诗","c":["画桥雕槛接招提，新有幽人榜秀溪。","十顷净明天上下，两奁光映水东西。","飞楼涌殿参差见，古木修篁咫尺迷。","此景此时君信否，绿杨阴里啭黄鹂。"]},{"t":"题北庄用陈勉仲韵","f":"五言律诗","c":["幽亭临水竹，云是使君庄。","秋霁来观稼，春融赋采桑。","纳凉供芡实，载酒摘莲房。","坐得牧民术，也应如牧羊。"]},{"t":"题四祖山瀑泉亭","f":"七言律诗","c":["云影曈昽雨弄晴，山头小立听溪声。","不惊赤日雷霆吼，但怪青天雪雹鸣。","气逼衣裳秋暑薄，光摇林薮午风轻。","法身清净元无垢，何用临流更濯缨。"]},{"t":"题合肥驿","f":"七言律诗","c":["重来岁月恍如飞，但怪芜城壁四围。","千里漫推新政善，几人能遂故园归。","云蒸残暑催登谷，风作新凉戒授衣。","小驿滞留朋旧绝，何妨白昼掩朱扉。"]},{"t":"题许公塞驿","f":"七言律诗","c":["遐想清游意欲飞，巢湖西畔碧山围。","高城别后骚人到，小驿春回燕子归。","壁上新诗留醉墨，庭前飞絮点征衣。","穷愁勿用频惆怅，来岁而今在北扉。"]},{"t":"题许公寨驿","f":"五言律诗","c":["畏景还迎日，追凉偶溯风。","泉声山上下，松影路西东。","远览心犹壮，清吟语自工。","雨多何所喜，郡国庆年丰。"]},{"t":"题时轩","f":"七言律诗","c":["图书堆里席凝尘，聊与时轩作主人。","自恐谢安行不免，谁言陶侃困无津。","东荣晓色高迎日，南圃花光得占春。","想见戴侯风味胜，轻弹珠玉到江滨。"]},{"t":"题法轮寺","f":"五言律诗","c":["孤塔云烟外，荒蹊草莽间。","蓼花红糁碎，枫叶绛绡殷。","送客三溪远，逢僧半日閒。","功名休览镜，沦落鬓毛斑。"]},{"t":"题宣州书堂山寺","f":"五言律诗","c":["书堂形胜好，山转与江抛。","泉古应黄蘖，亭新换白茅。","雨馀苍藓合，春晚绿阴交。","欲问香岩旨，风林竹自敲。"]},{"t":"题香岩与何希渊陈勉仲联辔","f":"五言律诗","c":["市井三墩北，招提百丈东。","晴云披叆叇，寒日弄曈昽。","滴沥林梢雨，凄凉盖影风。","我惭追骥足，策蹇走巴僮。"]},{"t":"题浮光丘家山寺","f":"七言律诗","c":["古寺钟鸣漏向残，马嘶人起束征鞍。","曈昽半弄阴晴日，栗烈初迎小大寒。","溪水断流寒冻合，野田飞烧晓霜乾。","嗟予老踏浮光路，陟岵怀亲眼欲酸。"]},{"t":"题黄梅驿舍壁间","f":"五言律诗","c":["石润占梅雨，山寒应麦秋。","清风鸣翠筱，疏雨湿红榴。","古驿苔封砌，荒城柳映楼。","高吟一瓯茗，聊为故人留。"]},{"t":"赠五祖山净老","f":"七言律诗","c":["欲知祖意路堂堂，满目湖山自放光。","林涌乱云迎马足，峰回荒磴上羊肠。","心花肯逐春同老，法雨何妨岁用康。","试向樵夫问端的，白莲生处是吾乡。"]},{"t":"赠古若之上人","f":"七言律诗","c":["滟潭澄碧见师心，我欲穷源何处寻。","万壑松风酬夜讽，一犁花雨发春吟。","不妨契阔三年别，却得留连数日阴。","竹外小桃开也未，灵云应已久披襟。"]},{"t":"赠严彦醇","f":"五言律诗","c":["一别三年久，重来两鬓苍。","瘦筇扶蹇步，新茗搅枯肠。","得句情还适，逢人话颇长。","湖山元不改，丧乱我心伤。"]},{"t":"赠遇公上人","f":"七言律诗","c":["卧云衣服半斓斑，吴越烟萝旧往还。","几度看涛罗刹石，经年寻药武夷山。","剃髭刃涩秋窗冷，补衲灯微夜榻閒。","应笑劳生苦多事，槐花时节入秦关。"]},{"t":"避寇姥山","f":"七言律诗","c":["山前湖水抱烟村，湖外山光隐若存。","泛宅浮家聊自托，荫松藉草欲谁论。","物情鱼沬真堪笑，世事槐安不在言。","回首故园煨烬里，归欤犹胜傍人门。"]},{"t":"避寇糁潭登李彦修延秀阁","f":"七言律诗","c":["王师千里下邦畿，三月宜新对敌围。","江上扁舟随处是，烟中华屋转头非。","逢人借问何时定，有客来传二圣归。","已办笭箵学元结，卜邻犹冀不相违。"]},{"t":"魏道弼父挽词代曾子修","f":"七言律诗","c":["德邵年高冠里闾，庆馀犹及魏公舒。","似闻白鹤归华表，应有青刍奠故庐。","帝梦漫惊虞涧筑，史占空叹渭滨渔。","泫然东望无从涕，莫厕邦人会葬车。"]},{"t":"对雪和子?用欧阳子韵","f":"五言古诗","c":["散漫来天际，高吟正倚门。","远山云母合，芳树柳花繁。","匝地银无价，冰湖鉴有痕。","何人穿敝履，有客拥高轩。","访戴从东棹，游梁快北辕。","鼎寒香屡拨，杯冷酒重温。","风力千林吼，云容万骑屯。","食馀盐虎卧，坐久炭猊蹲。","观舞更三叠，论文罄一樽。","清芬难掩覆，端的属梅园。"]},{"t":"次韵刘春卿书怀","f":"五言古诗","c":["老去宜安分，年来强竞辰。","功名虽自许，心腹欲谁陈。","赖有金溪彦，相从锦水滨。","词华三凤蔚，诗律八音纯。","风月论交旧，云山发兴新。","鄙怀烦澡雪，高义叹倾囷。","李峤真才子，唐邕实异人。","感时悲鹤战，忧国赋车辚。","寤寐思摧敌，行藏冀泽民。","廉高辞郑粟，狂笑取韩银。","松柏迷荆棘，琳琅杂珷珉。","北游观赤帻，西走避黄巾。","端木谋存鲁，长沙论过秦。","江湖双醉眼，天地一閒身。","遵海嗟黄屋，垂衣想紫宸。","擒王须李靖，抗贼付张巡。","尚缓三城役，方驰六辔询。","两河蜂伴蚁，多垒介和鳞。","烽火青淮隔，楼船古汴堙。","离宫埋茂草，禁籞掩荒榛。","典册尊诸夏，戎羌守四邻。","如何来丑类，容易破重闉。","大厦烟焚突，长堤蚁溃漘。","复垣阊阖夜，层观景龙春。","蔑视排奸魏，空闻识反甄。","伤哉无止鼠，甚矣不由鹑。","天启中兴运，时当外侮宾。","此生那习坎，吾道已康屯。","黄卷何妨对，青灯正可亲。","侏儒归檃括，苦窳入陶钧。","夸父劳追日，颜回怅绝尘。","庙堂资赞辅，岩穴忍跧踆。","炳焕文中虎，玲珑席上珍。","肯终虞涧筑，聊滞越山薪。","君壮勤非勉，予衰懒是真。","会看鸣鸑鷟，相庆画麒麟。","簪绂行当贵，齑盐莫厌贫。","仲尼忧悄悄，扬子恶频频。","守节身何屈，移忠道自伸。","秋吟足佳句，飞动笔如神。"]},{"t":"过富池题澄江阁二首 其二","f":"五言古诗","c":["江山南北限，风月古今情。","举酒杯还覆，逢人盖暂倾。","目穷飞鸟落，心逐断云横。","小市支残屋，严祠列画楹。","晚烟渔艇远，夏潦荻洲平。","试问濡须路，归欤过几城。"]},{"t":"过富池题澄江阁二首 其一","f":"五言古诗","c":["晚日千峰色，秋风万里情。","望云双目眩，渴雨寸心倾。","有客诗方就，何人笛正横。","渚烟萦别浦，江月动前楹。","草木腥犹在，生灵痛未平。","伤哉一杯酒，北向酹边城。"]},{"t":"和袁望回春雪","f":"五言古诗","c":["白雪嫌春晚，纵横布玉霙。","柳花随处发，瑶砌逐门成。","旌别寒松茂，摧残冻芋萌。","飘飖无限思，料峭有馀清。","舞袂朝犹湿，吟窗夜自明。","色疑侵两鬓，光欲眩双睛。","曭晃干林晓，潺湲万壑晴。","江梅含故态，山鸟弄新声。","雅与诗情惬，应怜病骨轻。","浇肠一杯酒，风力斗峥嵘。"]},{"t":"春雪和袁望回三首 其三","f":"五言古诗","c":["棱棱威正肃，浩浩意无涯。","雨息风还怒，霜馀雪更加。","氍毹还席地，薝卜竞分葩。","虎饿豺狼搏，乌穷鸟雀拿。","木冰鸣玉佩，檐溜轧芦芽。","鹤集疑惊露，羊群忆卧沙。","晚餐甘当肉，卯酒薄胜茶。","盈尺其多矣，踰旬果是耶。","日车行自驾，云障欲何遮。","坐想传柑饮，千官从翠华。"]},{"t":"春雪和袁望回三首 其二","f":"五言古诗","c":["谁谓过残腊，馀寒遂有涯。","雪来风益横，冰着雨还加。","万里隋堤絮，千山庾岭葩。","袁门晨尚闭，剡艇夜应拿。","百蛰犹含土，群芳敢放芽。","娇红还玉茗，新绿借金沙。","力胜榴花酒，功高雀舌茶。","人心愁甚矣，天意欲何耶。","好放朝阳出，休从宿雾遮。","青腰诚念我，明日变霜华。"]},{"t":"追和东坡立春韵寄彦逢弟","f":"五言古诗","c":["荏苒岁云暮，艰难予岂堪。","关山怀远别，弓矢废清谈。","风色霁还暖，梅梢春已酣。","信音惊远雁，心绪乱游蚕。","投笔班超近，擒戎李靖惭。","行吟望西北，赴难有虞潭。"]},{"t":"追和韩退之雪韵","f":"五言古诗","c":["一时符众望，七尺验童谣。","人喜丰穰兆，吾知瘴疠销。","戏看还扑面，閒试欲齐腰。","堕絮纷辞萼，飞花半惹条。","松篁低到地，溪涧合平桥。","月牖潜争入，风帘静自摇。","红金延坐夜，绿蚁送行朝。","暗上歌茵隰，轻随舞袖飘。","千林翻鲁缟，万里藉鲛绡。","灯市堪行乐，何妨酒价饶。"]},{"t":"送杨德润赴礼部试","f":"五言古诗","c":["雨意止还作，天容寒未舒。","无聊怀剧论，何幸过穷居。","举白夜酾酒，剪黄朝荐蔬。","新诗閒鼓吹，旧隐乱丘墟。","轩冕时何晚，山林计亦疏。","中兴屈群策，入告莫踌躇。"]},{"t":"送赵端质归朝","f":"五言古诗","c":["圣治中兴日，宗藩第一流。","九重资共理，三载赖分忧。","昨日交符虎，当时竞带牛。","咄嗟成药石，谈笑获锄耰。","善政称无扰，罢民遂有瘳。","教风兴子弟，膏泽被田畴。","士论高强汉，王功继屏周。","外台书课最，禁从表才猷。","往矣登青琐，宜哉建碧油。","疮痍争借寇，憔悴独依刘。","我愿攀鳞进，人思卧辙留。","是行端可喜，名姓在金瓯。"]},{"t":"菊有黄花为彦逢弟寿","f":"五言古诗","c":["正色憎桃李，凌霜见嫩黄。","有同高士操，常占晚秋芳。","袅袅金风软，漙漙玉露光。","君恩隆一束，时令应重阳。","幸遇桑蓬庆，欣逢曲米香。","敢因难老祝，采掇奉瑶觞。"]},{"t":"一经堂为王亦颜题","f":"五言古诗","c":["我生非我有，天地暂委形。","谛观子若孙，相值如浮萍。","崔昭与李兼，甚矣愚不灵。","积钱遗芸窟，转手还星星。","何如散籯金，人遗以一经。","韦贤不可作，高风看典型。","公家世植德，兰玉滋芳馨。","三鳣偶堕砌，伯鱼初过庭。","明明有圣训，言之尔其听。","退而学诗礼，斋扉昼长扃。","矻矻对月牖，孜孜守风棂。","冬映孙子雪，夜聚车公萤。","有时闻诵诗，流泉韵泠泠。","悬知睟见面，岩电仍双荧。","行当擢贤科，发策惊天廷。","致君此其术，何独取紫青。"]},{"t":"九江解舟顺风追和张文潜","f":"五言古诗","c":["朝来转西风，天巧借吾便。","解维溢江口，去若弦上箭。","水光漾朝曦，过浪掣惊电。","周旋谢神贶，冠坐敢不变。","斯须走四驿，俛仰蓦二县。","谁知久留滞，一旦乃适愿。","吾闻信由中，溪毛可羞荐。","咄哉和氏璞，底事待三献。","亨否自有时，时亨百无谴。","雷声在渊默，若讷故大辨。","千岩与万壑，左右供几砚。","落帆风亦止，璧月熨江练。"]},{"t":"上元后漕幕同僚二十八人会饮于西湖登千佛阁运干赵渔樵希圣以坡诗七言绝句分韵得陌字","f":"七言古诗","c":["福星台畔依红客，厌踏红尘穿紫陌。","涌金门外泛兰舟，两岸融融春水拍。","隔浦笙歌寄幽思，向阳花柳饶春色。","六桥突兀披丹青，千佛森罗眩金碧。","登临肯作怀古愁，志在云台书竹帛。","须臾饮散晚风号，却扫阴霾生桂魄。"]},{"t":"大柿行","f":"词","c":["君不见郑虔学书晚弥笃，岁收柿叶贮三屋。","兴来寝食两俱忘，但觉毛公老而秃。","又不见梓人造车度群木，木中无火柿所独。","旧言盖轸象乾坤，须信斡旋归一轴。","美哉此果有常德，结实何曾问荒熟。","霜馀万颗缀寒林，下视黄柑类奴仆。","牛心取象庶彷佛，熨斗得名何浼渎。","火乾既许暖关膈，冰冷当知解烦燠。","今年夏秋足时雨，尽道和气钟百谷。","西成仅得十之五，亦见阴阳有盈缩。","就中朱实繁且大，照野煌煌骇人目。","较之常岁远不侔，正似㪷胜难趁斛。","国家运厄困强敌，一纪于兹事弓韣。","空庭喋血在今年，我已不疑何更卜。","禾和鞋谐古云谶，大柿之祥天下福。","请赓继伐献吾君，王者功成四方服。"]},{"t":"大梁食李有感呈彦时兄","f":"七言古诗","c":["葵花已过荷花繁，南风入户清而温。","担头有李初入眼，令人引脰怀家园。","三年为客在两处，李熟未果登清樽。","翻思整冠诚可乐，何苦钻核辄不存。","急宜买冰致凝凛，全胜汲井供潺湲。","小床方簟嚼春雪，一实自可轻玙璠。","扁舟行逐东南奔，回首稻粱江上村。","相欢孰若弟与昆，古来唱和须篪埙。"]},{"t":"小桥","f":"五言律诗","c":["芳榭绕流水，春馀半篙绿。","登临赏幽花，兹亦我所欲。","小桥果何往，长堤正相属。","朝看龟鱼游，晚听鸥鹭浴。"]},{"t":"书怀示周少隐右司","f":"五言古诗","c":["我生动多艰，一笑不易得。","朅来坐逆旅，俯仰空太息。","吾人当代秀，文章擅华国。","分携十四载，复此见颜色。","匆匆未及款，归程忽云逼。","愿君因索涂，为我指南北。","金门与玉堂，努力事登陟。","閒将咫尺书，因风寄相忆。"]},{"t":"予绍兴三十二年夏四月三日行部至山中时月上人方入山十有八日旋披荆棘立数椽以居其徒明年改元隆兴夏六月二日再过山而堂室粗备且于云母泉侧创为茅亭使往来观者得以驻足而酌甘诚可嘉也时巴陵尉临川李克仁高密刘孝杰华容尉权三衢徐二誉在焉子辈侍行","f":"五言古诗","c":["去年入山时，孟夏暑犹薄。","来观云母泉，阴崖坐盘礴。","老禅披荆榛，经营始兴作。","山空斤斧响，丁丁振林壑。","俛仰恰周星，炎赫若凌薄。","昨朝发岳阳，东风怒还恶。","惊涛送轻舟，十里沙头落。","投凉不待晓，肩舆上硗确。","僧徒笑相迎，此意安可却。","高亭荫白茅，群峰峙青廓。","偕行二三子，临泉一杯酌。","呼僮瀹石鼎，煮汤旋和药。","谁令俗士驾，急去能不怍。","因成数句语，聊发后来噱。"]},{"t":"五祖山","f":"五言古诗","c":["我生事幽讨，尘埃良独难。","朅来舒蕲游，登临每长叹。","如何胜绝境，佛屋多所安。","大哉慈悲力，神功助劖刓。","住处未易言，小道亦可观。","五祖古名刹，楼台倚巑岏。","崎岖六七里，萦纡三百盘。","悬崖擢青士，夹道罗苍官。","飞泉响环玦，幽芳馥沉檀。","我来及新霁，千峰碧玉攒。","忽闻杞犬吠，旋觉壶天宽。","水声擢午暑，岚气生晚寒。","心目快开豁，腰脚嗟蹒跚。","看云更支筇，披风少凭栏。","欲营五亩宫，它年寄衰残。","试烦问祖师，莫作非意干。"]},{"t":"天宝歌和魏定公文次韵","f":"七言古诗","c":["连昌宫中马为乐，一时舞马黄金络。","君王养欲臣养文，忠鲠漫多宁救药。","嗷嗷万国风中船，樯倾柂坏夫何言。","潼关莫拒范阳贼，伤哉天厩空连钱。","翠华西去遥指蜀，应念霓裳旧家曲。","六军敢怒谁敢呵，马足空污太真肉。","始皇布漆徒坚城，元海斩木徒轻兵。","驱鱼驱雀强鹯獭，乃使后世蒙佳声。","乱离每忆升平日，忽对新诗重嗟泣。","望仙花草自春秋，怊怅六龙归未得。"]},{"t":"月台","f":"五言律诗","c":["低迷委径柳，氛氲被池莲。","亭前秋雨馀，明月来婵娟。","高台甃苍玉，清风夜周旋。","举杯属姮娥，醉舞还蹁跹。"]},{"t":"见山堂","f":"五言古诗","c":["浮云开西风，落木下夕阳。","谁人步东篱，采菊哦秋光。","悠然若有思，此意何可量。","南山适当前，翠色摩穹苍。","我心不期见，我眼偶相望。","咄哉逐兽夫，泰山空在旁。"]},{"t":"冬不雪春苦雨外台为民心恻檄郡请祷于法轮应感尊者悉获灵贶曾不终日教授有诗以发扬盛美郡人相山居士闻而悦之勉次其韵","f":"七言古诗","c":["谁令一日如三秋，仁人方念淮南州。","斯民忍饥望麰麦，积雨又有伤残忧。","冬温土燥生春瘴，半夜风声来枕上。","晓看飞雪欲堆檐，白马参差攒玉嶂。","年饥高下艺麦多，暴如山阜汸如河。","那知雪欲苦淫潦，两岐半吐翻随波。","欣闻万事一言了，使者勤民坐待晓。","指麾郡将率官僚，出郭共迎罗汉祷。","由来天意每因人，况自至诚宜感神。","明朝披雾走乌辔，晴光杲杲清无尘。","回头菽粟贱如水，醉饱田间摩腹觜。","周行四海不赍粮，可但携壶饷邻里。","出游遂继文昌谣，追锋行赴公车招。","快将刘晏干排手，衮衣入相禆唐尧。","广文才气迈燕许，分教芹宫从少驻。","政德稳步玉笋班，好尾輶轩上天去。"]},{"t":"古松","f":"五言律诗","c":["老松如蛟龙，气夺百万军。","根蟠苍崖石，梢拂青天云。","山神护野火，地主诃樵斤。","魁然栋梁材，为之献吾君。"]},{"t":"史佐才读书堂","f":"五言古诗","c":["我闻轮人扁，妙解书中义。","当其听读书，默识圣人意。","忽然释椎凿，有问发兹秘。","虽云圣人语，糟粕岂精粹。","齐侯诘其说，无说当致死。","请以斲轮观，固入要非易。","不徐仍不疾，心手在相契。","是中有数存，非言所能既。","扁也亦何人，所得乃至此。","固知斯道在，天下本无二。","观君榜斯堂，令我端拜议。","想见堂中书，填箱溢巾笥。","纵横三万卷，一览悉能记。","左右逢其原，下笔不能缀。","我昔摄东城，君时尚童稚。","如闻侍先公，往矣江之涘。","崎岖三十载，于此忽相值。","出示诸公诗，圭璧烂庭瑞。","君家依水竹，亭台缭幽邃。","作堂于其间，读书乃其事。","嗜好与人殊，可以见君志。","明年冠群英，先正秘书字。"]},{"t":"四祖山","f":"七言古诗","c":["黄梅西去一舍许，奔走龙天瞻四祖。","师今何往昔何来，占断金沙长作主。","须知至道本不灭，岂独高名固非取。","偶传衣钵继三世，遂配云中诏千古。","寺藏岩腹蟠地轴，塔据峰巅立天柱。","棱层石栈斜瓮玉，缭绕溪流缓萦组。","月明飞瀑百虹挂，风撼长松万蛟舞。","路通涧谷横略彴，树霭烟霞团缕数。","清阴扫径初入夏，苍藓封庭新过雨。","留连归客获联辔，邂逅主僧还接武。","请观异事花五叶，愿结胜缘香一缕。","何人为作锦鸡梦，此意他年铭肺腑。"]},{"t":"四面山午饭澡雪尘土往太湖二首 其二","f":"五言律诗","c":["重门掩松篁，杰阁戛霄汉。","溪流水晶软，石栈云母粲。","清游不可失，微劳敢言惮。","斜阳无相催，我欲濯尘汗。"]},{"t":"四面山午饭澡雪尘土往太湖二首 其一","f":"五言律诗","c":["白沙浥夜雨，苍松弄朝日。","清风满行路，骎骎马蹄疾。","溪声静如漱，岚翠浓欲滴。","我岂山中僧，前身饱游历。"]},{"t":"对雪二首再用前韵 其二","f":"五言古诗","c":["我笑袁司徒，闭户雪中市。","高眠罢炊爨，冰榻对瑶砌。","岂如王孝伯，鹤氅斗清媚。","随风杨柳花，纵横扑襟袂。","冬温犯春令，破白已为瑞。","何妨盈地尺，万井共欢慰。","草木含馀滋，山川郁佳气。","清寒入诗骨，敢问酒价倍。","日月同过鸟，燔烈又兴岁。","老大不足悲，吾今但心醉。"]},{"t":"对雪二首再用前韵 其一","f":"五言古诗","c":["同云昼暗空，孤城早休市。","行人失道路，贺客拥阶砌。","翻缟语亦工，飞絮思争媚。","飘飘何所似，想见六铢袂。","盈尺信为大，三白乃成瑞。","梅花不畏寒，点缀若相慰。","高吟撚冻须，诗社颇增气。","薰然一杯酒，神速功力倍。","来麰被馀润，预可占有岁。","便当呼老农，泼醅取沉醉。"]},{"t":"对雪和子厚弟四首 其四","f":"五言律诗","c":["瑶林我家风，银色佛世界。","泠泠一川水，淙玉漱寒濑。","敲冰往得鱼，拨冻自挑菜。","山居果如此，冷暖任交态。"]},{"t":"对雪和子厚弟四首 其二","f":"五言律诗","c":["前村不多地，坐觉阻且长。","梅花应已开，鼻观来清香。","天公爱衰朽，古木敲鸣珰。","僵仆巧耐寒，冰柱生承浆。"]},{"t":"对雪和子厚弟四首 其三","f":"五言律诗","c":["青腰夜种玉，不见稠与稀。","将军欲何往，滹沱正流澌。","软火烧黄精，我尔宁苦饥。","行行复行行，舌在请勿疑。"]},{"t":"对雪和子厚弟四首 其一","f":"五言律诗","c":["冻云不成雨，巧作白玉霙。","寒光僣晓色，报我东窗明。","起来拨残灰，煖酒手自倾。","多谢曲居士，于人殊有情。"]},{"t":"平沙雁落","f":"七言律诗","c":["雨馀湖水吞遥空，前山宿雾开溟濛。","坐看雁阵落沙觜，欲下复起摩苍穹。","寒芦飞花秋色老，乱扑客衣纷不扫。","肃肃惊风忽破行，却似张芝作颠草。"]},{"t":"用子蔺韵赋九日小酌","f":"七言古诗","c":["春日归来忽重九，潦旱相仍岁无有。","庭前岩桂独青青，此意于人亦良厚。","欲酬佳节拚一醉，会有白衣来送酒。","须臾殽核第罗列，无蟹犹空把螯手。","坐来灵雨洒珠玑，洗出湖山竞高秀。","三公在望无百里，咫尺银屏拥其后。","长篇落纸箭离筈，大白浮醪檐注溜。","细看黄菊与红茱，想像年时还话旧。","登高何必须人扶，我有筇杖颇坚瘦。","明朝写出醉中语，牵帅不知谁唱首。"]},{"t":"用东坡三峡桥韵赠源上人","f":"五言古诗","c":["解衣振林霏，攲枕听檐溜。","饥肠欲雷鸣，病耳忽牛斗。","自嗟兵火馀，十载困淮右。","崎岖穷水石，邂逅遍岩窦。","山游杂麋鹿，野处狎猿狖。","那知膏粱肥，但觉蔬笋瘦。","宝林吾北邻，晨夕钟鼓奏。","疏篁玉森列，樛木弓半彀。","来为圣人祝，歌呗发清昼。","归馀雨脚稀，溪流静如漱。"]},{"t":"白莲池","f":"五言古诗","c":["白莲如玉人，高洁谢脂泽。","圆荷作翠盖，掩映秋水碧。","小亭日相对，无言倚轻策。"]},{"t":"龙门呈心老","f":"五言古诗","c":["千山倚天高，一径穿云斜。","忽然见楼阁，知是佛子家。","苍松老不死，夭矫如龙蛇。","霜皮自鳞皴，风梢互槎牙。","幽花似薝卜，清绝不可加。","过庭送好音，异哉碧鸰伽。","我来不忍去，一步三咨嗟。","终当解冠裳，从师卧烟霞。"]},{"t":"会河道中","f":"五言律诗","c":["会河村店西，沙水清练练。","我行独带月，滉漾掣金线。","凝寒逼征衣，霜华重如霰。","至此怀僧弥，老泪几欲泫。"]},{"t":"再用奴字韵寄李廷吉","f":"七言古诗","c":["霜馀菊暗荷叶枯，千头喜见君家奴。","离离丹实照绿叶，不减五松官大夫。","迩来万木冻欲死，东君信到梅花须。","一枝亚竹斜照水，便觉清香无处无。","李君江南我江北，正如员峤邻方壶。","操修迥与世俗异，政事赖有神明扶。","文书甚简民甚喜，老吏往往寒无襦。","项侯秀发西楚后，作诗语带山仙癯。","愿因徐辟见孟子，折简未敢先招呼。","异时鼎社遂酣畅，会使王衍悲黄垆。"]},{"t":"再用前韵谢张济之见和","f":"五言古诗","c":["我欲访蓬莱，长笑挹浮丘。","此身插两翼，泠然御飕飗。","楼台耸琼瑶，草木丛珠球。","周旋于其间，不知尘世忧。","愿言久未遂，俛仰今白头。","茅斋夜飞雪，碎玉敲风瓯。","平生铁石肠，化作绕指柔。","年饥百无赢，接新待来麰。","君才似雕鹗，脩翎正横秋。","冲天在不日，入侍岩廊游。"]},{"t":"再用前韵谢潘寿卿见和二首 其二","f":"五言古诗","c":["新诗清绝俗，想见胸中丘。","飞泉落高峰，风声助飕飗。","又如清庙中，河图见天球。","不惟竦观瞻，玩之可忘忧。","是行何处来，楚尾连吴头。","一杯聊效芹，大似胜茶瓯。","赓我喜雪章，词情和且柔。","久旱民苦饥，重怜来与麰。","勃焉来争春，富哉麰向秋。","吾君德无边，今与和气游。"]},{"t":"再用前韵谢潘寿卿见和二首 其一","f":"五言古诗","c":["小人南郭綦，君子东家丘。","相从濡须坞，雪案风飕飗。","眼界眩兜绵，耳根鬨鸣球。","何妨具杯酌，一笑宽百忧。","不见刘带花，逢愁但摇头。","时来看崔卢，姓名覆金瓯。","我愿霁晨霜，栗烈还温柔。","黄金著高柳，绿浪翻来麰。","要令扶犁儿，力田遂逢秋。","饱食奚所须，鼓腹同天游。"]},{"t":"华亭风月堂避暑","f":"七言古诗","c":["大哉天休何穹窿，惟王配天居域中。","东西南北乃四裔，盛德可使车书同。","吾皇中兴继商武，小雅不复歌车攻。","年来幽障灭烽燧，梯航万里来夷戎。","华亭濒海古岩邑，商民填委百货通。","雕题交趾在何许，但见巨舰浮苍龙。","国家怀远固有道，缓征薄税垂无穷。","名官市舶司置长，往往所任多名公。","洪侯才望在人右，暂此出使良忡忡。","使台雄胜压湖水，飞桥百尺如垂虹。","作堂枕水傍风月，想见浩气盘高空。","我来五月过淫雨，炎云烈日方爞爞。","登临不独眼界豁，一洗烦暑清心胸。","偕行相遇二三子，吴赵与我并王钟。","高谈亹亹到莫逆，围棋把酒还从容。","轻风拂拂动襟袖，明月炯炯窥帘栊。","湖光十顷碧上下，身世恍在玻瓈宫。","何人倚槛正横笛，数声裂石开云峰。","忽然琵琶又继作，罄此百榼谁能供。","夜阑归去不成寝，卧听湖外鸣丰隆。"]},{"t":"吊魏敏功赠住庵通老","f":"五言律诗","c":["一别异生死，三年能几时。","埋玉不可见，拱木徒兴悲。","通老奉香火，坐阅岁月移。","圆颅点飞霜，夷旷真吾师。"]},{"t":"因纳上人寄题望江张氏春晖亭诗","f":"五言古诗","c":["青青原上草，初生殆毫芒。","迩来没蓬蒿，似有三尺强。","春晖主发生，万物资馀光。","迟迟虽不暴，萋萋自能长。","条风与谷雨，其功固难量。","予尝优劣之，岂得相辈行。","大哉发生恩，欲报不可偿。","东野古纯孝，作诗本肝肠。","怀亲感春晖，义见游子章。","凯风亦远矣，此道何茫茫。","惟馀东野诗，千古遥相望。","张公雷江人，鸡群鹤昂昂。","冰鱼与冬笋，志慕孟与王。","结庐守松楸，至行称淮乡。","我不识君面，因诗得其详。"]},{"t":"应资深康乐园四咏 其三","f":"七言律诗","c":["不知眼界几多阔，隐隐青山在天末。","湖光酿就琥珀浓，应助先生恣浇泼。","西风摇落黄花秋，江城有蟹供拍浮。","人如渊明亦不恶，肯使临赋成悠悠。"]},{"t":"应资深康乐园四咏 其一","f":"七言律诗","c":["溪头柳色春无际，溪水浮天一张纸。","东君戏草康乐园，旋入夭桃与繁李。","乱花无数不知名，往往倚槛窥前楹。","有时酒恶吐欲死，先生来约花间行。"]},{"t":"应资深康乐园四咏 其四","f":"七言律诗","c":["谁人独钓江南雪，雪满江南鸟飞绝。","先生对雪望江南，嗅认梅花忍寒折。","痴云捲尽清月流，小舟横卧南池头。","子猷乘兴欲何往，归欤莫为伊人留。"]},{"t":"应资深康乐园四咏 其二","f":"七言律诗","c":["露梢戛戛敲鸣玉，云叶差差传新绿。","亭前十顷碧琉璃，过雨荷花净如浴。","客来不迎君莫嗔，我有清风如故人。","先生午醉睡正熟，长须倒尽床头春。"]},{"t":"成相院","f":"五言律诗","c":["山前罗万松，邀我行数里。","不知幽人居，但爱乱峰峙。","新晴翠似泼，乍热汗如洗。","幸获听潺湲，何妨濯清泚。"]},{"t":"有荐胡仁叔为历阳令者仁叔以诗送知己暇日杨德润录以示予因次其韵","f":"五言古诗","c":["四海皆兄弟，三界是道场。","果且无彼我，安用分封疆。","胡公历阳来，气焰何可当。","威严走邸吏，不露太守章。","锦衣荣会稽，暮雨成高唐。","观望改侪辈，鸡群鹤昂昂。","斯民苦兵火，有意哀劳伤。","岂无九转丹，为助千金方。","古来记循吏，不称苟道将。","杀弟自取酷，防人人所防。","子潜去少室，渊明恋柴桑。","出处虽异事，一梦归黄粱。","昔日骨己朽，伤哉今也亡。","邶国歌柏舟，曹风赋鹈梁。","秋来河伯喜，未睹若与洋。","大小自有见，一笑还两忘。","我生分每越，泉石成膏肓。","弃遗等麟角，空虚漫龟肠。","常欲埋车轮，除奸继张纲。","召此人气和，致彼天时康。","语之有暇矣，未窥夫子墙。","理所不可及，马腹徒鞭长。","讵知王者师，异日韩张良。","愿言三顾庐，卧龙起南阳。"]},{"t":"次韩子云白莲韵","f":"五言古诗","c":["金缕不相称，纨素新裁衣。","坐令时世妆，屏迹从招挥。","施粉定太白，增分却成肥。","须知冰雪肌，秋月扬明辉。","来从姑射山，一洗百念非。","何烦障青绫，高谈解郎围。","亭亭翠盖中，老眼省见稀。","摇风自披拂，照水相因依。","傍观慎无前，恐犯丞相威。","不如太华巅，食藕家翠微。"]},{"t":"次韵子厚弟小春偶成","f":"七言律诗","c":["强插梨花做小春，风前诗思有馀清。","路逢野老那知姓，耳听幽禽自唤名。","岁晚山林松桧色，天寒关塞鼓鞞声。","枕流漱石君无笑，我欲岩居学子荆。"]},{"t":"次韵子厚弟喜雨行赠赵守端质","f":"七言古诗","c":["我生畏暑如畏焚，奈此岁旱风尘昏。","十年废放卧岩壑，名虽八品身黎元。","恒旸乞雨雨乞霁，雨转为淫旸转炽。","不知此理果何如，每讶天心异人意。","去年避地还家园，蒿莱满目高侵天。","秋阳肆虐冬益甚，涉春陂泽皆平川。","迩来焦稿遍区宇，黄金融液胶流弩。","赵侯日为疲瘵忧，应怪鲁书三不雨。","天人大抵常相资，顾我录录伤无奇。","鬻浆苦凉屠苦热，敢望屏翳从招麾。","圣主东巡群后觐，万里江淮方水运。","折冲禦侮赖亲贤，何独为霖福斯郡。","精诚昭格吾谁欺，顷间祷雨人所知。","忽然檐溜泻河汉，数声霹雳轰相随。","公堂六月清无暑，旋硙龙团试分乳。","官曹相贺复何言，且戒农夫筑场圃。","小人托庇安村墟，获同野老歌而呼。","愿公玉带悬金鱼，奉报得雨禾生稃。","霏霏不厌沾衣裾，稍晴欲自躬犁锄。","斯民食足吾其俱，何妨把酒仍观书。"]},{"t":"次韵王山甫春日出郊探梅","f":"五言古诗","c":["倚竹有佳人，天寒玉肌温。","永怀经年别，及此春日暄。","幽閒谁与娱，依依映丘樊。","计台二三友，才高工拨繁。","幕府公事退，联镳出郊原。","城南富卉木，胜处陈家园。","东风发萌芽，柳眼暗若昏。","昨宵一阵雨，清爽到乾坤。","植杖芳草径，系马枯桑根。","观梅不忍去，错俎罗金樽。","主人笑揖客，徘徊倚朱门。","指麾群儿辈，薪水相抚存。","邻妇抹红妆，来觇攀篱援。","酒酣诗思逸，笔力华旗搴。","姜盐芼芜菁，绝胜瓠叶幡。","萧然出尘姿，飘飘欲腾掀。","桃李分当避，蜂蝶那敢喧。","谁能移将归，栽培拥高垣。","要令百种花，俯伏争趋奔。","不烦频出游，正恐嘲短辕。","太簇初应律，飞霙尚翩翩。","何妨醉瑶舟，大嚼供炮燔。","手撚一枝春，吟笑穷曛暾。","可怜廊庙具，沉滞三家村。","和羹似不晚，作诗与招魂。"]},{"t":"次韵同年蔡仲平察院游西湖","f":"五言古诗","c":["朝日不受雾，晴光似晖晖。","忽然快我心，清风为解围。","坐见九里松，旌幢碧相依。","天竺了在望，上有祥云微。","西湖一千顷，圆荷覆青衣。","轻舟竞游览，往往俗客稀。","幸及新雨霁，欣逢露初晞。","水光与山色，高低映郊畿。","佳哉气葱郁，观阙何巍巍。","谁云门庭远，咫尺永天威。","诸公萃俊杰，高论玉麈挥。","载酒旨且多，不醉无庸归。","馀欢到献酢，滟滟双鸳飞。","新诗烂锦段，想见劳心机。","顾我虽百拙，续貂重相违。","明年若重来，种种当如几。"]},{"t":"次韵因上人晚菊简魏定父 其五","f":"五言律诗","c":["道人如青松，孤高不成丛。","爱此黄金花，萧然有淳风。","新诗皎秋月，警我野性慵。","佳意不在酒，此身今醉翁。"]},{"t":"次韵因上人晚菊简魏定父 其四","f":"五言律诗","c":["经年混蒿艾，蕴藏应待时。","清香密渍沉，微风助纷披。","宋玉昧秋意，乃作儿女悲。","君子有所养，因君观解颐。"]},{"t":"次韵因上人晚菊简魏定父 其三","f":"五言律诗","c":["离索自可笑，衰迟谁见怜。","亭亭摇落中，一枝小窗前。","正色有家法，细看清且妍。","浮觞未云晚，松醪吾所便。"]},{"t":"次韵因上人晚菊简魏定父 其一","f":"五言律诗","c":["荆棘困松柏，风雨乱昏晓。","干戈几时息，年来费天讨。","孤芳如谢安，端恐非小草。","此意谁人知，伊余相自保。"]},{"t":"次韵因上人晚菊简魏定父 其六","f":"五言律诗","c":["介寿诚有取，无问人所宜。","君看菊花潭，事见桃源诗。","东坡百世士，敢比流俗知。","相逢勿相失，不醉欲何时。"]},{"t":"次韵因上人晚菊简魏定父 其二","f":"五言律诗","c":["不学桃与李，芬芳竞春时。","天公岂多情，清露为君迟。","荣悴休问命，冷暖当自知。","青荧夜窗灯，相对哦新诗。"]},{"t":"次韵因上人晚菊简魏定父 其七","f":"五言律诗","c":["黄花如故人，别久喜复面。","浇泥一杯酒，安用较深浅。","清霜开浮云，黄落信风捲。","岩岩幽素姿，秋来不多见。"]},{"t":"次韵因老见赠","f":"五言古诗","c":["扁舟历阳来，访君得少息。","登堂默无语，见者称目击。","去年糁江上，群盗罗剑戟。","君时濡须游，入山笑相揖。","肩担祖师禅，问答挥即栗。","岂惟警聋瞆，亦足慰岑寂。","春容褪丹青，雨意铺水墨。","定将傥赴感，澄霁自端的。","麦秋数日间，饥肠颇贪得。","兵馀敝庐尽，何独空四壁。","维摩幸无恙，胡避有新室。","白云本无心，能归定能出。","岿然三杰峰，况是旧相识。","我有半仙丹，和剂等菖术。","为言山中人，蟠桃已成实。"]},{"t":"次韵因老胡避游","f":"七言古诗","c":["新诗滚滚江流东，一泻万里谁能穷。","平生清峭不近俗，雪山突兀江头峰。","相逢一笑莫相避，自古高人苦难致。","涪翁骨冷唤不醒，且向新诗求笔势。","君于涪翁真后身，有同次律前身僧。","语言直下见理窟，何须辛苦从张凭。","对君令我思秋菊，三月褒山如一宿。","君看玉局感秋吟，叹息流光岂予独。"]},{"t":"次韵孙兴宗秋怀","f":"七言古诗","c":["秋山赫赫明丹枫，秋天隐隐分玄鸿。","不知眼界阔多少，九华突兀撑晴空。","嗟予老病百事懒，谁能强勉追儿童。","读书既苦齿多豁，属文益觉心如蓬。","年来衰甚更龃龉，乘舟卖面皆遭风。","茫茫有类堕云海，踌躇四顾迷西东。","感君赋秋肯寄我，开缄反覆歌三终。","如痿忽起盲忽视，角力未易分雌雄。","寒乡冰雪正凝冱，暖回爱日何烘烘。","惊涛巨浸浩无际，安流利涉输艨艟。","荜门圭窦仅容膝，规模敢拟阿房宫。","生平未惯新斧凿，斲削便许从共工。","伟哉欧梅两黄鹄，逃名诗酒俱称翁。","余生顾后八十载，贤愚虽异襟期同。","知君尚友取前哲，言之聊复输丹衷。","何为规规事骚雅，乃欲索我章句中。","舂容大轴烂锦绣，令人一睹情融融。","清新妩丽似鲍谢，岂徒奥学称淹通。","人能平地覆一篑，不辍会致邱山崇。","披云俛仰三百日，相逢底事常匆匆。","去年江上识君处，凿冰初见阳冲冲。","分携不觉秋又晚，向来旱气方蕴隆。","君如镇西我淝水，我往无事还何功。","而君被檄试多士，考覈曲尽权衡公。","作诗恶用求好语，好语正自添诗穷。","有时嗣响姑趁韵，兹意祇欲安微躬。","争如闭门绝庆吊，著书远继吾家充。","静言培塿亦何罪，不韪正坐睎衡嵩。","茅斋雨过风露肃，青灯夜讽赓秋虫。","更阑耿耿不成寐，卧听江城鸣画筒。"]},{"t":"次韵朱元顺食萱草羹","f":"五言古诗","c":["衰年因羁旅，百念日萦绕。","蓍龟亦何知，忧来又将老。","出处稍不慎，远志成小草。","堂阴有孤芳，纷葩照人好。","谁将忘忧姿，撷芼等蘋藻。","充肠固甚慰，入鼎可堪扰。","糠籺贫者事，甚矣兄逐嫂。","异时餍粱肉，记此一羹饱。"]},{"t":"次韵毕少董游西湖","f":"七言古诗","c":["西湖春晚未全热，湖上山光互明灭。","往来冠盖竞骈阗，断续笙箫共伊咽。","我怜湖山山见怜，波间涌出佳人钿。","太真一去不复返，圆荷万点胭脂钱。","船头美眄珠的皪，不必洞房深处觅。","忽然相值更相呼，嫩蓝衫子山争碧。","肠断骚人一轴诗，细看烟柳想腰肢。","明年我亦西湖去，迟日光风二月时。"]},{"t":"次韵许志仁","f":"五言古诗","c":["我技类族庖，用刀常月更。","君才妙天下，游刃得我惊。","前年获相值，因忆吴中行。","一别忽两载，依然旧交情。","新诗璧夜光，厥价轻连城。","相思不可见，把玩我愿盈。","笔札擅南州，文章动西京。","行矣秋风高，更听宾鸿声。"]},{"t":"次韵张文伯喜雨","f":"七言古诗","c":["新诗句句堪流传，令人读之神凛然。","孟君已死不可见，如公笔力今无前。","天生百谷养万姓，暄润稍阙功难全。","江城秋旱望一溉，斯民穷极伊谁怜。","滂沱忽澍三尺雨，稿苗厌厌藨绵绵。","不知何以遽得此，有贤太守方承宣。","焚香默祷辞未绝，精诚已格高高天。","油云垂布若可揽，沾濡车盖初言旋。","西成指日多黍稌，颂歌未负赓丰年。","豚蹄盂酒谢神贶，鼓腹一笑非予偏。"]},{"t":"次韵沈次韩见赠","f":"五言古诗","c":["我狂众所易，赖有君见容。","十年卧岩壑，百念付一空。","新诗似流泉，涓涓江汉供。","人言鸡群鹤，我目霜中松。","相距无两舍，会见何溟濛。","谁能写离索，正藉诗思工。"]},{"t":"次韵陈勉仲二首 其二","f":"七言律诗","c":["十载穷愁鸟出笼，春来天意似通融。","得书故旧颇相悯，上疏朝廷应见容。","开府莫辞金帛尽，犁庭当冀祲氛空。","庙堂素定平戎策，不待文渊在目中。"]},{"t":"次韵陈勉仲二首 其一","f":"七言律诗","c":["蜂喜春晴竞出笼，雪明篱脚眼看融。","柳条借日还金色，梅萼因风动玉容。","窥牖数声禽度曲，过庭千字雁书空。","青毡笑指吾家物，芳草无边一望中。"]},{"t":"次韵陈勉仲登群山观","f":"五言古诗","c":["十年放江湖，亲朋益疏散。","不知跬步间，游览有奇观。","因君寄新诗，心目益悽断。","东城俯荻洲，下有鱼鸟乱。","想见江南山，终日对书案。","小立筇杖倚，兀坐葛巾岸。","高情渺云外，竑议涉唐汉。","嗟予衰且老，儿辈逼婚冠。","岂复敢言诗，观诗重增叹。","舂容来大轴，玩味起顽懦。","穷愁欲谁知，富贵当自断。","探虎愧吕蒙，思鲈抗张翰。","别来能几时，鬓发暗凋换。","养成杜甫懒，甘作元结漫。","何当遂拂衣，疲马解缰绊。","卜邻大期东，携酒日相看。"]},{"t":"次韵胡德辉松轩时乞兵戍淮","f":"词","c":["伐蛟生得须髯苍，隐然为屋分三梁。","广寒恍若东西厢，清风入座衣披猖。","萧萧终日声奏篁，一洗郑卫无伊凉。","嗟予顽钝铁石肠，时危命蹇甘皇皇。","江城正苦夏烈日，淮甸已惧秋飞霜。","绿尊翠杓且径醉，喜与夫子参翱翔。","平生丘壑老增剧，梦想朝露珠玑香。","何时元戎北渡森旗章，料敌制胜一一尽所长，鸡群野鹤看昂昂。"]},{"t":"次韵赵积中慈湖即事 其一","f":"七言绝句","c":["江南七月旱不雨，捲地风霾翳寰宇。","夷门先生有底忙，车马东游亦良苦。"]},{"t":"次韵赵积中慈湖即事 其三","f":"七言绝句","c":["入室儿童隘函丈，想见綵衣还谑浪。","挂冠如欲赋田园，一水淮乡足閒旷。"]},{"t":"次韵赵积中慈湖即事 其六","f":"七言绝句","c":["平生可惯偿诗债，追骥疲驽况加怠。","不妨对客自挥毫，文社于今有淮海。"]},{"t":"次韵徐伯源九日閒居追和渊明","f":"五言古诗","c":["閒居遇重九，对酒怀陶生。","陶生不可见，爱此重九名。","清霜肃时令，天宇增高明。","依依远山色，隐隐宾鸿声。","泛酒黄金花，人言可延龄。","嗟予不解饮，酒到从之倾。","嫣然木芙蓉，摇风倚东荣。","虽无窈窕歌，自足娱吾情。","鼓琴复何为，年来泯亏成。"]},{"t":"次韵秦寿之雷江阻风","f":"七言古诗","c":["君之是行亦不恶，到处名山得佳作。","江神好事欲援例，横起狂风捲帆脚。","要求诗句须少驻，故戏舟师令暂泊。","雷江正在淮南岸，万顷黄芦映青廓。","不知眼界阔多少，但见炊烟耿墟落。","归心浩浩孰撩动，归梦忡忡予忖度。","怒涛底事强留滞，清夜无眠屡惊愕。","溯游初冀日千里，今比驱车反成错。","人生离合自有数，谁谓江神能见谑。","新诗入笔走骅骝，奔逸绝尘那可却。","何妨有酒发妙思，坐对陶泓自斟酌。","韵严语险属和难，顾我才悭子非虐。"]},{"t":"次韵秦寿之题五祖","f":"七言律诗","c":["栽花传法总吾身，生灭无烦取次论。","一梦傥从今日觉，群峰应许此山尊。","塔中相好如来具，手里衣盂达磨存。","若遇小儿宜借问，性华何处更寻根。"]},{"t":"次韵袁望回见赠兼简杨德润","f":"七言古诗","c":["长堤十里荷花雨，隐约尘头南去路。","故人恋恋不能忘，又遣长须寄新语。","锦囊玉轴缠朱丝，开缄恍觉云烟飞。","青山未许松柏老，绿野会致牛羊肥。","嗟予衰滞烦訾相，十年相对江湖上。","苦吟猛省爆鸭脚，剧论旋惊烂熊掌。","分携令我重回首，日月漂流易成久。","因风频寄数行书，毋蹈从前作诗瘦。","比邻先生倦不出，德齿俱尊时第一。","何妨杖屦日过逢，白酒黄鸡醉秋色。"]},{"t":"次韵陶监丞茂安见赠","f":"七言古诗","c":["三年重见须川湄，舍舟东去何驱驰。","王事靡盬莫遑息，人生所贵心相知。","经从往返两过我，一言意厚何多为。","向来江夏倾盖日，翕然誉望推麟仪。","才猷伏火丹九转，用之功效堪扶衰。","重阳初过雨新霁，乾坤六合方平夷。","边城残寇何足灭，庙堂胜算那容窥。","相逢问我出世法，嗟我茅塞同荒陂。","因君扣击发深省，沉迷可笑群昏随。","我闻摩诘老居士，后身楼至今王维。","忽然惠顾有缘契，恍若宿雾青天披。","愿君为我取妙善，此界示现无边慈。"]},{"t":"次韵高守无隐苦热","f":"七言律诗","c":["郁蒸还起炮车云，旱气方隆雨未能。","应念开帱来白鸟，故成洒酒聚青蝇。","南皮痛饮君当继，北牖高眠我独醒。","人仰郡侯清可倚，暑中真是一条冰。"]},{"t":"次韵寄荀晋仲简陈夫子","f":"七言古诗","c":["二老亭亭双属玉，交映霜馀半溪绿。","才高一世妙言语，落笔珠玑烂盈掬。","时来钓叟为三公，傅岩莘野谁雌雄。","纷纷俗态任冷煖，风云早晚腾蛟龙。","中兴复见宣和盛，须信人心协天命。","真从僵仆正邦基，更向膏肓起民病。","尺书寄我三长篇，管中窥豹非其全。","墨渝纸敝未释手，晴窗飞尽沉香烟。","嗟予留滞濡须坞，梦寐斯文属燕许。","何当单骑造斋榻，遂使高轩出城府。","春风回首归萌芽，又促畦丁种早瓜。","我心倾写会有日，为言已办浮江槎。"]},{"t":"次韵慧上人见寄","f":"五言古诗","c":["别来六改岁，想遍江南山。","江南二百州，云水相往还。","秦望冠吴越，嵯峨俯尘寰。","法华在其侧，参差拥高鬟。","幽花自芬芳，好鸟时缗蛮。","传闻发梦寐，登览忘劬艰。","去年谒老聪，默坐焚金颜。","忽然狮子吼，顿觉醒冥顽。","子今从之游，旧习须夷删。","人人自有分，既悟不我悭。","请看钓鱼翁，满船载鲂鳏。"]},{"t":"次韵魏定文","f":"五言古诗","c":["半年去城府，寤寐溪东扉。","有时得君书，想像抉石猊。","岂知纪渻子，养气如养鸡。","应响与疾视，一洗三旬非。","我生坐穷困，哆侈伤南箕。","鼷鼠亦何物，焉用千钧机。","封侯絣澼絖，药等手不龟。","所用有异耳，此言寓非卮。","梅蕾良可人，如椒缀南枝。","芬芳想不晚，太皞方执视。"]},{"t":"江天暮雪","f":"七言律诗","c":["冻云垂地风栗冽，万里江天暮飞雪。","九华何处正嶙峋，琼树瑶林斗明洁。","扁舟突兀依寒芦，朝来残酒犹半壶。","夜寒独酌不成醉，卧听宿雁鸣相呼。"]},{"t":"灯下读魏彦成诸公诗因次其韵呈曾子修诸君","f":"五言古诗","c":["距春尚旬月，春信已回柳。","时来芝与菌，往往出粪朽。","流俗不自重，困穷变操守。","贵贱等人耳，未易遽薄厚。","桃李何敢轻，所报必瑶玖。","一笑置勿论，旨有君子酒。"]},{"t":"西灵鹫","f":"五言古诗","c":["我闻西灵鹫，幽奇冠龙舒。","山神知我来，夜雨自涤除。","篮舁犯霏微，敢惮石径纡。","清风偃林柯，征衣尽沾濡。","樵人向我言，君行欲何如。","松杉已在望，尚有七里馀。","崎岖雨过水，蹊云上天衢。","飞楼及涌殿，峥嵘映浮屠。","幽鸟若相喜，好音弄笙竽。","为言一宿觉，何妨更踟蹰。"]},{"t":"西湖游次韵赵见烛","f":"七言古诗","c":["山镇在越泽在吴，东南形势凭江湖。","不知弱水竟何处，恍若员峤连方壶。","海门潮至飞雪涌，天竺雨过遥青纡。","十年不见看愈好，正复妙笔那能图。","苍松摇风翠盖偃，芳草藉地柔茵铺。","僧舍朝游恣登览，酒楼夕醉争歌呼。","朅来俛仰春又晓，对花无语空长吁。","作诗既非拙者事，强欲写书编泽蒲。","伟哉得志佐明主，进退百辟称鸿儒。","应怜伺候奔走辈，终日趑趄仍嗫嚅。"]},{"t":"过白羊市","f":"五言律诗","c":["小市环农亩，长桥接佛宫。","扁舟帆影日，幽鸟柳阴风。","沙觜浅深水，树梢红白茸。","乍闻秋籴贱，吾亦庆年丰。"]},{"t":"过集湖德济庙用赵尉廉留题韵示周钦夫程彦游","f":"七言古诗","c":["秋阳汎汎流清晖，帆腹不张旂脚垂。","灵祠轮奂湖之麋，水天一色成玻瓈。","西轩爽垲高不危，凭栏下瞰群山卑。","鬼神亮我心无欺，风涛纵险夫何疑。","区区奔走劳驱驰，和光未免世俗随。","相逢一笑聊伸眉，明朝掺袂还东之。","萧曹有节未见奇，往往樵牧相鄙夷。","吾生倾否会有时，穷愁过眼无足悲。"]}]};